window.VML_DONNEES_EMBARQUEES = {"enigmes":{"_commentaire":"Généré par outils/immersif/migrer-jeu.py depuis « renaissance ». À compléter : voir MIGRATION-RAPPORT.md.","version":1,"niveaux":[{"id":"matelot","nom":"Compagnon","icone":"🔧","equivalent":"≈ CM1","profil":"cœur de programme CM1"},{"id":"timonier","nom":"Maître","icone":"🧭","equivalent":"≈ CM2","profil":"cœur de programme CM2"}],"escales":[{"numero":1,"id":"l-imprimerie-de-maitre-jacquet-la-renaissance-et-l-humanisme","titre":"L'imprimerie de Maître Jacquet","lieu":"Une imprimerie de la ville d'Amboise, au printemps 1518","matiere":"","periode_conseillee":"","episode":"Des livres frais sortent de la presse : des textes latins et grecs, des traductions, des almanachs. Sur le mur, la gravure d'un temple romain à colonnes.","scenarimage":"","mot":"ANTIQUITÉ","mot_origine":"Le mot-clé de la salle 1.","air":null,"cinematique_ouverture":"transition-e1","cinematique_fin":"fin-e1","etats_decor":[],"enigmes":[{"id":"e1-1","escale":1,"ordre":1,"titre":"La frise de Maître Jacquet","decor":"imprimerie","objet_principal":"objet-1","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"jacquet","probleme_narratif":"Maître Jacquet veut une frise exacte pour sa page.","enjeu":"Sans repères, on mélange les époques.","episode_du_roman":"Château royal d'Amboise (notice de visite) ; Encyclopédie Larousse, « Renaissance » et « Gutenberg » ; Vikidia, « François Ier de France »","competence_programme":"Expliquer le mot Renaissance","pourquoi_ce_savoir_ici":"La salle « L'imprimerie de Maître Jacquet — La Renaissance et l'humanisme » repose sur cette notion.","reaction_du_decor":{"effet":"calme","description":"Les caractères d'imprimerie s'alignent sur la presse."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"renaissance-humanisme","type":"ordre","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"L'Antiquité (les Grecs et les Romains) vient d'abord, puis le Moyen Âge. Vers 1450, Gutenberg met au point l'imprimerie. En 1496, Charles VIII revient d'Italie avec des artistes italiens. En 1515, François Ier devient roi ; en 1516, Léonard de Vinci s'installe à Amboise. La Renaissance redécouvre l'Antiquité, après le Moyen Âge.","matelot":{"items":[{"txt":"Les Grecs et les Romains bâtissent des temples et sculptent des statues","sous":"l'Antiquité","rang":1},{"txt":"On construit des châteaux forts et des cathédrales","sous":"le Moyen Âge","rang":2},{"txt":"Gutenberg met au point l'imprimerie","sous":"vers 1450","rang":3},{"txt":"François Ier devient roi de France","sous":"1515","rang":4}],"consigne":"Remets ces moments dans l'ordre, du plus ancien (en haut) au plus récent (en bas). Utilise les flèches ▲ et ▼, puis vérifie.","indices":["Les Grecs et les Romains vivaient il y a plus de 2 000 ans.","Les châteaux forts viennent avant l'imprimerie.","François Ier est le plus récent."],"dialogue":"Bonjour, jeunes gens. Une page de carnet est tombée dans ma cour. Je l'ai gardée, car elle parle de mon métier. Grâce à l'imprimerie, un livre se fabrique en centaines d'exemplaires. On imprime les textes des anciens Grecs et Romains, que les savants redécouvrent. Tout le monde parle d'un temps nouveau, venu d'Italie. Dites-moi d'où il vient, et la page est à vous."},"timonier":{"items":[{"txt":"Les Grecs et les Romains bâtissent des temples à colonnes","sous":"l'Antiquité","rang":1},{"txt":"On construit des châteaux forts et des cathédrales gothiques","sous":"le Moyen Âge","rang":2},{"txt":"Gutenberg met au point l'imprimerie à caractères mobiles, à Mayence","sous":"vers 1450","rang":3},{"txt":"Charles VIII revient d'Italie avec des artistes italiens","sous":"1496","rang":4},{"txt":"François Ier devient roi de France","sous":"1515","rang":5},{"txt":"Léonard de Vinci s'installe à Amboise","sous":"1516","rang":6}],"consigne":"Classe ces six moments du plus ancien au plus récent. Lis bien les dates.","indices":["L'Antiquité et le Moyen Âge n'ont pas de date ici : ce sont les plus anciens.","1450 vient avant 1496.","Le roi d'abord, puis l'artiste qu'il invite."],"dialogue":"Bonjour, jeunes gens. Une page de carnet est tombée dans ma cour. Je l'ai gardée, car elle parle de mon métier. Grâce à l'imprimerie, un livre se fabrique en centaines d'exemplaires. On imprime les textes des anciens Grecs et Romains, que les savants redécouvrent. Tout le monde parle d'un temps nouveau, venu d'Italie. Dites-moi d'où il vient, et la page est à vous."}},{"id":"e1-2","escale":1,"ordre":2,"titre":"Les mots de la Renaissance","decor":"imprimerie","objet_principal":"objet-2","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"helene","probleme_narratif":"Dame Hélène associe les mots de la Renaissance à leur sens.","enjeu":"Sans les mots, on ne comprend pas la Renaissance.","episode_du_roman":"Encyclopédie Larousse, « Renaissance », « humanisme » et « Gutenberg » ; Lumni","competence_programme":"Expliquer le mot Renaissance","pourquoi_ce_savoir_ici":"La salle « L'imprimerie de Maître Jacquet — La Renaissance et l'humanisme » repose sur cette notion.","reaction_du_decor":{"effet":"carte","description":"La pile de livres se range en rayons."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"renaissance-humanisme","type":"association","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"La Renaissance, aux XVe et XVIe siècles, est l'époque où l'on redécouvre l'art et les savoirs de l'Antiquité. Elle commence en Italie, à Florence. Les humanistes étudient les textes anciens et pensent que l'homme peut progresser par le savoir. L'imprimerie de Gutenberg permet de multiplier les livres.","matelot":{"paires":[{"g":"La Renaissance","d":"époque où l'on redécouvre l'art de l'Antiquité"},{"g":"L'Antiquité","d":"époque des Grecs et des Romains"},{"g":"L'imprimerie","d":"technique pour fabriquer beaucoup de livres"}],"consigne":"Relie chaque mot à sa définition : clique sur un mot, puis sur la bonne définition.","indices":["« Re-naissance » : quelque chose renaît.","Les Grecs et les Romains vivaient pendant l'Antiquité.","Une machine pour faire des livres."],"dialogue":"Humanisme, imprimerie, mécène… Associez chaque mot à son sens."},"timonier":{"paires":[{"g":"La Renaissance","d":"aux XVe et XVIe siècles, redécouverte de l'art et des savoirs antiques"},{"g":"Un humaniste","d":"savant qui étudie les textes anciens et croit au progrès par le savoir"},{"g":"Gutenberg","d":"met au point l'imprimerie à caractères mobiles"},{"g":"Florence","d":"ville d'Italie où la Renaissance commence"},{"g":"L'Antiquité","d":"époque des Grecs et des Romains, prise pour modèle"}],"consigne":"Relie chaque mot ou nom à sa définition. Lis toute la phrase avant de choisir.","indices":["Humaniste vient du latin humanus, « humain ».","Florence est une ville d'Italie.","Gutenberg travaillait à Mayence, en Allemagne."],"dialogue":"Humanisme, imprimerie, mécène… Associez chaque mot à son sens."}},{"id":"e1-3","escale":1,"ordre":3,"titre":"Pourquoi « renaître » ?","decor":"imprimerie","objet_principal":"objet-3","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"colombe","probleme_narratif":"Colombe demande pourquoi on parle de renaissance.","enjeu":"Sans comprendre, le mot Renaissance reste vide.","episode_du_roman":"Encyclopédie Larousse, « Renaissance » et « humanisme » ; Collège de France, « Cinq siècles d'histoire »","competence_programme":"Expliquer le mot Renaissance","pourquoi_ce_savoir_ici":"La salle « L'imprimerie de Maître Jacquet — La Renaissance et l'humanisme » repose sur cette notion.","reaction_du_decor":{"effet":"ouverture","description":"La presse imprime une page toute fraîche."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"renaissance-humanisme","type":"qcm","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"La Renaissance commence en Italie, au XVe siècle : artistes et savants admirent l'Antiquité et veulent la faire « renaître ». L'imprimerie diffuse vite les livres et les idées. Les humanistes apprennent le latin, le grec et l'hébreu pour lire les textes anciens.","matelot":{"questions":[{"q":"Que veut dire le mot « Renaissance » ?","options":["on fait renaître l'art et les savoirs de l'Antiquité","le roi est né une deuxième fois","on reconstruit les châteaux forts"],"bonne":0,"explication":"Les artistes et les savants prennent les Grecs et les Romains pour modèles."},{"q":"Dans quel pays la Renaissance commence-t-elle ?","options":["en Italie","en Angleterre","en Égypte"],"bonne":0,"explication":"À Florence, au XVe siècle."},{"q":"À quoi sert l'imprimerie ?","options":["à fabriquer beaucoup de livres plus vite","à peindre des tableaux","à construire des ponts"],"bonne":0,"explication":"Avant, les livres étaient copiés à la main, un par un."}],"consigne":"Lis chaque question, puis clique sur la bonne réponse. Quand tu as tout répondu, clique sur « Vérifier ».","indices":["Re-naissance : naître à nouveau.","Léonard de Vinci vient de ce pays.","Avant l'imprimerie, on recopiait les livres à la main."],"dialogue":"Pourquoi dit-on « Renaissance » ? Répondez aux questions."},"timonier":{"questions":[{"q":"Qu'est-ce qu'un humaniste ?","options":["un savant qui étudie les textes anciens et croit au progrès par le savoir","un soldat du roi","un moine qui recopie les livres","un marchand d'épices"],"bonne":0,"explication":"Guillaume Budé, conseiller de François Ier, est un grand humaniste."},{"q":"Quelles langues anciennes les humanistes apprennent-ils ?","options":["le latin, le grec et l'hébreu","l'anglais et l'allemand","le chinois","le breton et le basque"],"bonne":0,"explication":"En 1530, les premiers lecteurs royaux enseignent le grec, l'hébreu et les mathématiques."},{"q":"Qu'imitent les architectes de la Renaissance ?","options":["les colonnes et les formes régulières des monuments antiques","les huttes des Gaulois","les donjons de bois","les pyramides"],"bonne":0,"explication":"Symétrie, colonnes, frontons : l'Antiquité sert de modèle."},{"q":"Pourquoi l'imprimerie aide-t-elle les idées de la Renaissance à se répandre ?","options":["un même livre est fabriqué en beaucoup d'exemplaires","les livres deviennent interdits","on n'écrit plus de livres","seul le roi peut lire"],"bonne":0,"explication":"Les livres circulent dans toute l'Europe."}],"consigne":"Réponds aux quatre questions, puis vérifie. Une seule réponse est exacte à chaque fois.","indices":["Les humanistes veulent lire les textes anciens dans leur langue d'origine.","Pense aux colonnes des temples grecs.","Un livre imprimé se fait en beaucoup d'exemplaires."],"dialogue":"Pourquoi dit-on « Renaissance » ? Répondez aux questions."}},{"id":"e1-4","escale":1,"ordre":4,"titre":"La page de Maître Jacquet","decor":"imprimerie","objet_principal":"objet-4","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"bastien","probleme_narratif":"Bastien relit la page de Maître Jacquet.","enjeu":"Sans les mots, la page ne peut pas être imprimée.","episode_du_roman":"Encyclopédie Larousse, « Renaissance » et « humanisme » ; Collège de France, « Cinq siècles d'histoire »","competence_programme":"Expliquer le mot Renaissance","pourquoi_ce_savoir_ici":"La salle « L'imprimerie de Maître Jacquet — La Renaissance et l'humanisme » repose sur cette notion.","reaction_du_decor":{"effet":"lumiere","description":"La page se couvre de lettres noires bien nettes."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"renaissance-humanisme","type":"trous","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"Née en Italie au XVe siècle, la Renaissance gagne la France au XVIe siècle. Les humanistes étudient les textes de l'Antiquité ; l'imprimerie diffuse leurs livres. François Ier crée en 1530 les lecteurs royaux, qui enseignent gratuitement le grec, l'hébreu et les mathématiques.","niveaux":["timonier"],"timonier":{"texte":"<p>La Renaissance commence en [[Italie]] au XVe siècle. Les artistes admirent les monuments de l'[[Antiquité]]. Les [[humanistes]] lisent les textes anciens en latin, en [[grec]] et en hébreu. Grâce à l'[[imprimerie]], leurs livres circulent dans toute l'Europe. En 1530, François Ier crée les lecteurs [[royaux]], qui enseignent gratuitement.</p>","etiquettes":["Italie","Antiquité","humanistes","grec","imprimerie","royaux","Égypte","Moyen Âge","chevaliers","télévision"],"consigne":"Complète la page imprimée par Maître Jacquet. Clique sur une étiquette, puis sur le trou où elle va. Quatre étiquettes sont en trop.","indices":["Le pays où tout commence est au sud des Alpes.","Les savants qui étudient les textes anciens sont les…","En 1530, le roi crée les lecteurs…"],"dialogue":"La page de Maître Jacquet est incomplète. Retrouvez les mots."}}]},{"numero":2,"id":"la-grande-salle-d-amboise-francois-ier-roi-mecene","titre":"La grande salle d'Amboise","lieu":"La grande salle du château royal d'Amboise","matiere":"","periode_conseillee":"","episode":"On accroche des tapisseries, on dresse les tables. Sur les murs, la lettre F couronnée et des salamandres. Par les fenêtres, on voit la Loire.","scenarimage":"","mot":"MÉCÈNE","mot_origine":"Le mot-clé de la salle 2.","air":null,"cinematique_ouverture":"transition-e2","cinematique_fin":"fin-e2","etats_decor":[],"enigmes":[{"id":"e2-1","escale":2,"ordre":1,"titre":"Vrai ou faux, Dame Hélène ?","decor":"salle","objet_principal":"objet-1","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"helene","probleme_narratif":"Dame Hélène teste vos connaissances sur François Ier.","enjeu":"Croire une idée fausse sur le roi, c'est mal le juger.","episode_du_roman":"Vikidia, « François Ier de France » et « Ordonnance de Villers-Cotterêts » ; Château royal d'Amboise ; Collège de France","competence_programme":"Situer le règne de François Ier","pourquoi_ce_savoir_ici":"La salle « La grande salle d'Amboise — François Ier, roi mécène » repose sur cette notion.","reaction_du_decor":{"effet":"carte","description":"Un rayon de lumière frappe le trône."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"francois-mecene","type":"vraifaux","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"François Ier devient roi le 1er janvier 1515 et gagne la bataille de Marignan la même année, en Italie. Il invite Léonard de Vinci en France. Il protège les arts et les lettres : c'est un mécène. En 1539, l'ordonnance de Villers-Cotterêts impose le français dans les actes de justice et d'administration, sans interdire les langues régionales.","matelot":{"affirmations":[{"txt":"François Ier devient roi de France en 1515.","vrai":true,"explication":"Le 1er janvier 1515."},{"txt":"Léonard de Vinci est un roi d'Italie.","vrai":false,"explication":"C'est un artiste et un ingénieur italien, invité par le roi."},{"txt":"François Ier aide et protège les artistes : c'est un mécène.","vrai":true,"explication":"Il les invite, les loge et les paie."},{"txt":"François Ier a gagné la bataille de Marignan.","vrai":true,"explication":"En 1515, en Italie."}],"consigne":"Pour chaque phrase, clique sur « Vrai » ou sur « Faux », puis vérifie.","indices":["François Ier devient roi en 1515.","Léonard est un artiste, pas un roi.","Un mécène aide et paie les artistes."],"dialogue":"Bienvenue au château d'Amboise. Le roi a grandi ici, vous le saviez ? Depuis qu'il est roi, il fait venir d'Italie des peintres, des sculpteurs, des savants. Il aime aussi les livres et les langues. Mais attention, c'est aussi un roi qui fait la guerre. La page que j'ai ramassée parle de lui. Montrez-moi que vous le connaissez."},"timonier":{"affirmations":[{"txt":"François Ier remporte la bataille de Marignan, en Italie, en septembre 1515.","vrai":true,"explication":"Les 13 et 14 septembre 1515, près de Milan."},{"txt":"Léonard de Vinci est un roi d'Italie.","vrai":false,"explication":"C'est un artiste invité, logé et pensionné par le roi."},{"txt":"François Ier invite des artistes italiens en France.","vrai":true,"explication":"Léonard de Vinci, Benvenuto Cellini, le Primatice…"},{"txt":"En 1539, l'ordonnance de Villers-Cotterêts impose le français dans les actes de justice et d'administration.","vrai":true,"explication":"Le latin y est remplacé par le français."},{"txt":"L'ordonnance de Villers-Cotterêts interdit de parler breton ou occitan chez soi.","vrai":false,"explication":"Elle ne concerne que les actes officiels."},{"txt":"Les lecteurs royaux, créés en 1530, enseignent gratuitement.","vrai":true,"explication":"C'est l'origine de l'actuel Collège de France."}],"consigne":"Pour chaque affirmation, réponds « Vrai » ou « Faux », puis vérifie. Attention aux idées reçues.","indices":["Marignan est en Italie, près de Milan.","L'ordonnance concerne les actes officiels, pas la langue parlée chez soi.","Les lecteurs royaux enseignent gratuitement."],"dialogue":"Bienvenue au château d'Amboise. Le roi a grandi ici, vous le saviez ? Depuis qu'il est roi, il fait venir d'Italie des peintres, des sculpteurs, des savants. Il aime aussi les livres et les langues. Mais attention, c'est aussi un roi qui fait la guerre. La page que j'ai ramassée parle de lui. Montrez-moi que vous le connaissez."}},{"id":"e2-2","escale":2,"ordre":2,"titre":"La vie du roi","decor":"salle","objet_principal":"objet-2","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"colombe","probleme_narratif":"Colombe range les étapes de la vie du roi.","enjeu":"Sans l'ordre, on ne comprend pas son règne.","episode_du_roman":"Vikidia, « François Ier de France » ; Château royal d'Amboise ; Collège de France","competence_programme":"Situer le règne de François Ier","pourquoi_ce_savoir_ici":"La salle « La grande salle d'Amboise — François Ier, roi mécène » repose sur cette notion.","reaction_du_decor":{"effet":"ouverture","description":"Les portraits se placent le long du mur."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"francois-mecene","type":"ordre","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"François Ier naît à Cognac en 1494 et passe son enfance au château d'Amboise. Il devient roi le 1er janvier 1515 et gagne à Marignan en septembre 1515. Léonard de Vinci s'installe à Amboise en 1516. En 1530, le roi crée les lecteurs royaux ; en 1539, l'ordonnance de Villers-Cotterêts impose le français dans les actes officiels.","matelot":{"items":[{"txt":"François naît à Cognac","sous":"1494","rang":1},{"txt":"Enfant, il grandit au château d'Amboise","sous":"son enfance","rang":2},{"txt":"Il devient roi et gagne la bataille de Marignan","sous":"1515","rang":3},{"txt":"Il invite Léonard de Vinci à Amboise","sous":"1516","rang":4}],"consigne":"Remets la vie de François Ier dans l'ordre, du plus ancien (en haut) au plus récent (en bas).","indices":["On naît avant de grandir.","Il devient roi avant d'inviter Léonard.","Regarde les années sous chaque carte."],"dialogue":"La vie du roi se raconte dans l'ordre. Rangez les événements."},"timonier":{"items":[{"txt":"Naissance de François, le 12 septembre 1494, à Cognac","rang":1},{"txt":"François devient roi, le 1er janvier 1515","rang":2},{"txt":"Victoire de Marignan, les 13 et 14 septembre 1515","rang":3},{"txt":"Léonard de Vinci s'installe au manoir du Cloux, en 1516","rang":4},{"txt":"Création des lecteurs royaux, en 1530","rang":5},{"txt":"Ordonnance de Villers-Cotterêts, en août 1539","rang":6}],"consigne":"Classe ces six événements du règne de François Ier, du plus ancien au plus récent. Aucune date n'est rappelée : appuie-toi sur le texte.","indices":["Naissance, enfance, puis le règne.","Le 1er janvier vient avant septembre.","Les lecteurs royaux (1530) viennent avant Villers-Cotterêts (1539)."],"dialogue":"La vie du roi se raconte dans l'ordre. Rangez les événements."}},{"id":"e2-3","escale":2,"ordre":3,"titre":"Le roi protège…","decor":"salle","objet_principal":"objet-3","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"bastien","probleme_narratif":"Bastien trie ceux que le roi protège.","enjeu":"Sans le tri, on ne voit pas qui le roi soutient.","episode_du_roman":"Vikidia, « François Ier de France » ; Collège de France ; Château de Chambord","competence_programme":"Situer le règne de François Ier","pourquoi_ce_savoir_ici":"La salle « La grande salle d'Amboise — François Ier, roi mécène » repose sur cette notion.","reaction_du_decor":{"effet":"lumiere","description":"La tapisserie s'illumine."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"francois-mecene","type":"tri","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"François Ier est un mécène des arts : il invite Léonard de Vinci, fait bâtir Chambord, collectionne des tableaux italiens. Il protège aussi les lettres : lecteurs royaux (1530), dépôt légal des livres (1537), français dans les actes officiels (1539). C'est aussi un roi guerrier, qui combat en Italie (Marignan, 1515).","matelot":{"colonnes":[{"id":"arts","titre":"Les arts"},{"id":"lettres","titre":"Les lettres"}],"cartes":[{"txt":"Il invite Léonard de Vinci","col":"arts"},{"txt":"Il fait construire Chambord","col":"arts"},{"txt":"Il achète des tableaux italiens","col":"arts"},{"txt":"Il crée les lecteurs royaux","col":"lettres"},{"txt":"Il rassemble des livres dans sa bibliothèque","col":"lettres"},{"txt":"Il impose le français dans les actes officiels","col":"lettres"}],"consigne":"Range chaque carte : est-ce pour les arts (peinture, architecture) ou pour les lettres (livres, langues) ? Clique sur une carte, puis sur une colonne.","indices":["Les lettres, ce sont les livres et les langues.","Chambord est une œuvre d'architecture.","Trois cartes par colonne."],"dialogue":"Le roi protège les artistes et les savants. Triez ce qu'il protège."},"timonier":{"colonnes":[{"id":"arts","titre":"Les arts"},{"id":"lettres","titre":"Les lettres"},{"id":"guerre","titre":"La guerre"}],"cartes":[{"txt":"Il invite Léonard de Vinci, puis le Primatice","col":"arts"},{"txt":"Il fait commencer Chambord en 1519","col":"arts"},{"txt":"Il collectionne des tableaux italiens","col":"arts"},{"txt":"Il crée les lecteurs royaux (1530)","col":"lettres"},{"txt":"Il crée le dépôt légal des livres imprimés (1537)","col":"lettres"},{"txt":"Il impose le français dans les actes officiels (1539)","col":"lettres"},{"txt":"Il remporte la bataille de Marignan (1515)","col":"guerre"},{"txt":"Il mène des guerres en Italie pour le duché de Milan","col":"guerre"}],"consigne":"Range chaque action du roi dans la bonne colonne : les arts, les lettres, ou la guerre.","indices":["Marignan va dans la colonne de la guerre.","Le dépôt légal concerne les livres imprimés.","Les tableaux italiens vont avec les arts."],"dialogue":"Le roi protège les artistes et les savants. Triez ce qu'il protège."}},{"id":"e2-4","escale":2,"ordre":4,"titre":"Le coffret de Dame Hélène","decor":"salle","objet_principal":"objet-4","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"tommaso","probleme_narratif":"Tommaso cherche le code du coffret.","enjeu":"Sans le code, le coffret reste fermé.","episode_du_roman":"Collège de France, « Cinq siècles d'histoire » ; Vikidia, « Ordonnance de Villers-Cotterêts » ; Château royal d'Amboise","competence_programme":"Situer le règne de François Ier","pourquoi_ce_savoir_ici":"La salle « La grande salle d'Amboise — François Ier, roi mécène » repose sur cette notion.","reaction_du_decor":{"effet":"eclat","description":"Le coffret s'ouvre sur un parchemin."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"francois-mecene","type":"code","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"Les lecteurs royaux sont créés en 1530 ; l'ordonnance de Villers-Cotterêts date de 1539. Le château royal d'Amboise, où François Ier a grandi, est le lieu où il invite Léonard de Vinci.","niveaux":["timonier"],"timonier":{"champs":[{"libelle":"Année de la création des lecteurs royaux","valeur":"1530","longueur":4},{"libelle":"Année de l'ordonnance de Villers-Cotterêts","valeur":"1539","longueur":4},{"libelle":"Le château royal où le roi a grandi (7 lettres)","valeur":"AMBOISE","longueur":7,"numerique":false}],"consigne":"Le coffret de Dame Hélène est fermé par un cadenas. Écris les deux années et le nom demandés (les accents ne comptent pas), puis ouvre.","indices":["Les lecteurs royaux : une année qui finit par 30.","Villers-Cotterêts : neuf ans plus tard.","Le château où tu te trouves : A… (7 lettres)."],"dialogue":"Ce coffret garde un secret. Trouvez le code."}}]},{"numero":3,"id":"l-atelier-du-cloux-leonard-de-vinci","titre":"L'atelier du Cloux","lieu":"L'atelier de Léonard, au manoir du Cloux, près du château","matiere":"","periode_conseillee":"","episode":"Des feuilles couvertes de dessins : des visages, des machines, des oiseaux, des tourbillons d'eau. Sur un chevalet, un portrait de femme au sourire léger.","scenarimage":"","mot":"OBSERVER","mot_origine":"Le mot-clé de la salle 3.","air":null,"cinematique_ouverture":"transition-e3","cinematique_fin":"fin-e3","etats_decor":[],"enigmes":[{"id":"e3-1","escale":3,"ordre":1,"titre":"Une œuvre, un talent","decor":"atelier","objet_principal":"objet-1","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"tommaso","probleme_narratif":"Tommaso associe chaque œuvre à un talent.","enjeu":"Sans connaître ses talents, on réduit Léonard.","episode_du_roman":"Château royal d'Amboise (notice de visite 2026) ; Château du Clos Lucé ; Musée du Louvre (La Joconde) ; Vikidia, « Homme de Vitruve » ; Ency","competence_programme":"Présenter Léonard de Vinci","pourquoi_ce_savoir_ici":"La salle « L'atelier du Cloux — Léonard de Vinci » repose sur cette notion.","reaction_du_decor":{"effet":"ouverture","description":"Les œuvres s'illuminent l'une après l'autre."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"leonard-de-vinci","type":"association","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"Léonard est à la fois peintre (la Joconde, un portrait commencé vers 1503), dessinateur et savant (l'Homme de Vitruve, vers 1490, sur les proportions du corps), observateur de la nature (le vol des oiseaux, l'anatomie) et ingénieur (projets de machines, de canaux, de palais). Beaucoup de ses machines sont restées sur le papier.","matelot":{"paires":[{"g":"La Joconde","d":"peinture : un portrait"},{"g":"La machine volante de ses carnets","d":"invention dessinée, jamais construite"},{"g":"Le vol des oiseaux","d":"observation de la nature"}],"consigne":"Relie chaque œuvre de Léonard au talent qu'elle montre : clique sur une œuvre, puis sur la bonne étiquette.","indices":["La Joconde est un tableau.","Une machine dessinée, c'est une invention.","Regarder voler les oiseaux, c'est observer la nature."],"dialogue":"Voici l'atelier de mon maître. Le roi lui a donné ce manoir et un beau titre : premier peintre, ingénieur et architecte du roi. Le maître peint, dessine des machines, imagine des canaux, et il regarde tout : l'eau, les oiseaux, les plantes. Ses pages sont un vrai désordre ! La troisième page est ici, quelque part. Aidez-moi à la retrouver."},"timonier":{"paires":[{"g":"La Joconde","d":"portrait peint à l'huile, commencé vers 1503"},{"g":"L'Homme de Vitruve","d":"dessin sur les proportions du corps humain"},{"g":"La machine volante","d":"projet d'invention resté sur le papier"},{"g":"Les études d'anatomie","d":"observation du corps humain"},{"g":"Les projets de canaux et de palais","d":"travail d'ingénieur et d'architecte pour le roi"}],"consigne":"Relie chaque œuvre ou projet de Léonard à ce qu'il montre de lui.","indices":["L'Homme de Vitruve est dans un cercle et un carré.","La machine volante n'a jamais volé.","Pour le roi, il imagine des canaux et un palais."],"dialogue":"Voici l'atelier de mon maître. Le roi lui a donné ce manoir et un beau titre : premier peintre, ingénieur et architecte du roi. Le maître peint, dessine des machines, imagine des canaux, et il regarde tout : l'eau, les oiseaux, les plantes. Ses pages sont un vrai désordre ! La troisième page est ici, quelque part. Aidez-moi à la retrouver."}},{"id":"e3-2","escale":3,"ordre":2,"titre":"Le désordre des carnets","decor":"atelier","objet_principal":"objet-2","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"jacquet","probleme_narratif":"Jacquet trie les carnets.","enjeu":"Sans tri, on perd ses idées.","episode_du_roman":"Château royal d'Amboise (notice de visite 2026) ; Château du Clos Lucé ; Musée du Louvre (La Joconde) ; Vikidia, « Homme de Vitruve » ; Ency","competence_programme":"Présenter Léonard de Vinci","pourquoi_ce_savoir_ici":"La salle « L'atelier du Cloux — Léonard de Vinci » repose sur cette notion.","reaction_du_decor":{"effet":"lumiere","description":"Les carnets se rangent par sujet."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"leonard-de-vinci","type":"tri","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"Les carnets de Léonard mêlent tout : esquisses de tableaux, machines, plans, mais aussi des plantes, des animaux, l'eau, le corps humain. Pour lui, peindre exige d'observer et de comprendre la nature.","matelot":{"colonnes":[{"id":"peintre","titre":"Le peintre"},{"id":"inventeur","titre":"L'inventeur"}],"cartes":[{"txt":"Un visage de femme qui sourit","col":"peintre"},{"txt":"Une esquisse de tableau","col":"peintre"},{"txt":"Les plis d'une robe, au crayon","col":"peintre"},{"txt":"Une machine à ailes","col":"inventeur"},{"txt":"Un pont qu'on peut démonter","col":"inventeur"},{"txt":"Des engrenages et des roues dentées","col":"inventeur"}],"consigne":"Les pages de Léonard sont mélangées. Range chaque page : peintre ou inventeur ? Clique sur une page, puis sur une colonne.","indices":["Un portrait, c'est le travail du peintre.","Un pont, une machine : le travail de l'inventeur.","Trois pages par colonne."],"dialogue":"Les carnets de Léonard sont en désordre. Triez-les."},"timonier":{"colonnes":[{"id":"peintre","titre":"Le peintre"},{"id":"inventeur","titre":"L'ingénieur-inventeur"},{"id":"observateur","titre":"L'observateur de la nature"}],"cartes":[{"txt":"Une esquisse de portrait","col":"peintre"},{"txt":"Les plis d'un drapé","col":"peintre"},{"txt":"Une machine à ailes battantes","col":"inventeur"},{"txt":"Le projet d'un canal pour le roi","col":"inventeur"},{"txt":"Des engrenages","col":"inventeur"},{"txt":"Le vol d'un oiseau, aile par aile","col":"observateur"},{"txt":"Les tourbillons de l'eau","col":"observateur"},{"txt":"Une plante dessinée avec ses racines","col":"observateur"}],"consigne":"Range chaque page des carnets : le peintre, l'ingénieur-inventeur, ou l'observateur de la nature.","indices":["Les plantes, les oiseaux, l'eau qui tourbillonne : l'observateur.","Les machines et les canaux : l'ingénieur.","Les visages et les drapés : le peintre."],"dialogue":"Les carnets de Léonard sont en désordre. Triez-les."}},{"id":"e3-3","escale":3,"ordre":3,"titre":"L'intrus du Cloux","decor":"atelier","objet_principal":"objet-3","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"helene","probleme_narratif":"Hélène repère l'intrus du Cloux.","enjeu":"Un intrus embrouille les carnets.","episode_du_roman":"Château royal d'Amboise (notice de visite 2026) ; Château du Clos Lucé ; Musée du Louvre (La Joconde) ; Vikidia, « Homme de Vitruve » ; Ency","competence_programme":"Présenter Léonard de Vinci","pourquoi_ce_savoir_ici":"La salle « L'atelier du Cloux — Léonard de Vinci » repose sur cette notion.","reaction_du_decor":{"effet":"eclat","description":"L'intrus quitte la table."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"leonard-de-vinci","type":"intrus","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"Léonard naît en 1452 à Vinci, en Italie. Invité par François Ier, il s'installe en 1516 au manoir du Cloux (aujourd'hui le Clos Lucé), à Amboise, avec le titre de premier peintre, ingénieur et architecte du roi. Il y meurt le 2 mai 1519. Ses machines volantes sont restées des dessins : aucune n'a volé.","matelot":{"cartes":[{"txt":"Il naît en Italie, à Vinci","sous":"en 1452","intrus":false},{"txt":"Il peint la Joconde","sous":"un portrait célèbre","intrus":false},{"txt":"Il vit ses dernières années à Amboise","sous":"au manoir du Cloux","intrus":false},{"txt":"Il remplit des carnets de dessins","sous":"des milliers de pages","intrus":false},{"txt":"Il devient roi de France","sous":"en 1515","intrus":true}],"consigne":"Une seule carte est fausse à propos de Léonard. Clique sur l'intrus, puis vérifie.","indices":["Léonard est un artiste, pas un roi.","Il a vécu ses dernières années en France.","Quatre cartes sont vraies."],"dialogue":"Un objet n'a rien à faire dans cet atelier. Lequel ?"},"timonier":{"cartes":[{"txt":"Il s'installe au manoir du Cloux","sous":"en 1516","intrus":false},{"txt":"Il devient premier peintre, ingénieur et architecte du roi","sous":"titre donné par François Ier","intrus":false},{"txt":"Il apporte la Joconde en France","sous":"le roi l'acquiert ensuite","intrus":false},{"txt":"Il meurt à Amboise","sous":"le 2 mai 1519","intrus":false},{"txt":"Il fait voler sa machine volante devant le roi","sous":"dans les jardins du Cloux","intrus":true}],"consigne":"Une seule carte est fausse à propos de Léonard. Attention aux légendes ! Trouve l'intrus, puis vérifie.","indices":["Ses machines volantes sont restées dans les carnets.","Il meurt à Amboise en 1519.","Le roi lui donne un titre : premier peintre, ingénieur et architecte."],"dialogue":"Un objet n'a rien à faire dans cet atelier. Lequel ?"}},{"id":"e3-4","escale":3,"ordre":4,"titre":"Le mot à l'envers","decor":"atelier","objet_principal":"objet-4","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"colombe","probleme_narratif":"Colombe cherche le mot à l'envers.","enjeu":"Sans le miroir, l'écriture reste secrète.","episode_du_roman":"Château royal d'Amboise (notice de visite 2026) ; Château du Clos Lucé ; Musée du Louvre (La Joconde) ; Vikidia, « Homme de Vitruve » ; Ency","competence_programme":"Présenter Léonard de Vinci","pourquoi_ce_savoir_ici":"La salle « L'atelier du Cloux — Léonard de Vinci » repose sur cette notion.","reaction_du_decor":{"effet":"calme","description":"Le miroir renvoie le mot à l'endroit."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"leonard-de-vinci","type":"lettres","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"Léonard remplit des carnets de notes et de dessins toute sa vie, souvent en écriture inversée (de droite à gauche). Beaucoup de ces pages sont aujourd'hui conservées dans des bibliothèques et des musées d'Europe.","niveaux":["timonier"],"timonier":{"cible":["C","A","R","N","E","T","S"],"texte":"<p>Au manoir, le maî<b data-l='T'>t</b>re dessine sans cesse. Sur sa table s'empilent des feuilles couvertes de machines, de vi<b data-l='S'>s</b>ages et de plantes. Il obse<b data-l='R'>r</b>ve les oiseaux, puis il note tout, de droite à gauche, comme dans un <b data-l='M'>m</b>iroir. Ses p<b data-l='A'>a</b>ges sont reliées en petits cahiers. Le soir, Tommaso range l'<b data-l='E'>e</b>ncre, les plumes et les <b data-l='C'>c</b>rayons, et il souffle la bougie. Le matin, tout recommence, sans jamais finir : Léonard ne cesse d'appre<b data-l='N'>n</b>dre, et de <b data-l='D'>d</b>essiner.</p>","consigne":"Léonard écrivait souvent de droite à gauche, comme dans un miroir. Trouve l'objet où il notait tout : clique les lettres en couleur pour les ranger dans les cases, dans l'ordre qui forme le mot (7 lettres). Attention aux lettres pièges.","indices":["Un petit cahier qu'on garde dans sa poche.","Le mot commence par C.","Il finit par S : il y en a plusieurs."],"dialogue":"Léonard écrivait à l'envers. Remettez le mot dans le bon sens."}}]},{"numero":4,"id":"le-cabinet-des-plans-les-chateaux-de-la-renaissance","titre":"Le cabinet des plans","lieu":"Le cabinet des plans, au château d'Amboise","matiere":"","periode_conseillee":"","episode":"Sur une grande table, des plans de châteaux : Amboise, Blois où l'on construit une aile nouvelle, et le projet d'un château immense dans la forêt de Chambord.","scenarimage":"","mot":"SALAMANDRE","mot_origine":"Le mot-clé de la salle 4.","air":null,"cinematique_ouverture":"transition-e4","cinematique_fin":"fin-e4","etats_decor":[],"enigmes":[{"id":"e4-1","escale":4,"ordre":1,"titre":"Le plan de Chambord","decor":"plans","objet_principal":"objet-1","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"colombe","probleme_narratif":"Colombe veut légender le plan de Chambord.","enjeu":"Sans plan, on ne reconnaît pas le château.","episode_du_roman":"Académie de Nice, fiche « Le château de Chambord » (EAC) ; Vikidia, « Château de Chambord » ; plan schématique simplifié","competence_programme":"Comparer château fort et château de la Renaissance","pourquoi_ce_savoir_ici":"La salle « Le cabinet des plans — Les châteaux de la Renaissance » repose sur cette notion.","reaction_du_decor":{"effet":"lumiere","description":"Le plan de Chambord se déploie."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"chateaux-renaissance","type":"plan","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"Au centre de Chambord se dresse le donjon carré (1), avec ses quatre tours. Au cœur du donjon, l'escalier à double révolution (2) dessert des salles disposées en croix (3). Une enceinte relie de grandes tours d'angle (4) ; dans les ailes se trouvent les appartements du roi (5) et la chapelle (6). Tout est symétrique.","matelot":{"titre":"Le plan de Chambord","colonnes":2,"cases":[{"libelle":"Repère 1 — le grand carré au centre","reponse":"Le donjon"},{"libelle":"Repère 2 — l'escalier tout au centre","reponse":"L'escalier à double révolution"},{"libelle":"Repère 4 — en bas à gauche","reponse":"Une tour d'angle"},{"libelle":"Repère 6 — en haut à gauche","reponse":"La chapelle"}],"consigne":"Colombe déplie le plan de Chambord, vu de dessus. Clique sur une étiquette, puis sur la case du bon repère.<svg viewBox=\"0 0 340 240\" role=\"img\" aria-label=\"Plan schématique du château de Chambord vu de dessus, avec des repères numérotés\" style=\"display:block;max-width:440px;margin:10px auto;background:#eef2df;border:2px solid #8a7a5a;border-radius:10px\">\n<rect x=\"14\" y=\"20\" width=\"312\" height=\"208\" rx=\"18\" fill=\"#9cc3d8\" stroke=\"#4d7489\"/>\n<rect x=\"40\" y=\"48\" width=\"260\" height=\"154\" fill=\"#e6dcc4\" stroke=\"#6e6452\" stroke-width=\"5\"/>\n<g fill=\"#cfc2a3\" stroke=\"#6e6452\" stroke-width=\"3\"><circle cx=\"40\" cy=\"48\" r=\"20\"/><circle cx=\"300\" cy=\"48\" r=\"20\"/><circle cx=\"40\" cy=\"202\" r=\"16\"/><circle cx=\"300\" cy=\"202\" r=\"16\"/></g>\n<rect x=\"118\" y=\"28\" width=\"104\" height=\"104\" fill=\"#d9ccb0\" stroke=\"#3d352b\" stroke-width=\"3\"/>\n<g fill=\"#cfc2a3\" stroke=\"#3d352b\" stroke-width=\"2.5\"><circle cx=\"118\" cy=\"28\" r=\"14\"/><circle cx=\"222\" cy=\"28\" r=\"14\"/><circle cx=\"118\" cy=\"132\" r=\"14\"/><circle cx=\"222\" cy=\"132\" r=\"14\"/></g>\n<g fill=\"#f3ead6\" stroke=\"#8a7a5a\"><rect x=\"161\" y=\"34\" width=\"18\" height=\"92\"/><rect x=\"124\" y=\"71\" width=\"92\" height=\"18\"/></g>\n<circle cx=\"170\" cy=\"80\" r=\"9\" fill=\"#b98a3e\" stroke=\"#5e3f1f\" stroke-width=\"1.5\"/><path d=\"M170 72 A8 8 0 0 1 178 80 M170 88 A8 8 0 0 1 162 80\" stroke=\"#5e3f1f\" fill=\"none\"/>\n<text x=\"170\" y=\"222\" font-size=\"9\" text-anchor=\"middle\" font-family=\"Georgia,serif\" fill=\"#2b1d10\">schéma simplifié, sans échelle</text>\n<g font-family=\"Georgia,serif\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#2b1d10\"><circle cx=\"150\" cy=\"50\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"150\" y=\"55\">1</text><circle cx=\"170\" cy=\"92\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"170\" y=\"97\">2</text><circle cx=\"46\" cy=\"198\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"46\" y=\"203\">4</text><circle cx=\"46\" cy=\"54\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"46\" y=\"59\">6</text></g>\n</svg>","indices":["Le repère 1 est le grand carré au milieu.","Le repère 2 est tout au centre : un escalier en rond.","Les repères 4 et 6 sont des tours rondes aux angles."],"dialogue":"Bonjour ! Je m'appelle Colombe, mon père est maître maçon. Ici, on dessine les châteaux du roi. Ce ne sont plus des forteresses : on veut de grandes fenêtres, des escaliers magnifiques, tout bien symétrique, comme dans l'Antiquité. Le roi rêve d'un château encore plus grand, à Chambord. Lisez les plans avec moi, et je vous donne la page."},"timonier":{"titre":"Le plan de Chambord","colonnes":3,"cases":[{"libelle":"Repère 1","reponse":"Le donjon"},{"libelle":"Repère 2","reponse":"L'escalier à double révolution"},{"libelle":"Repère 3","reponse":"Les salles en croix"},{"libelle":"Repère 4","reponse":"Une tour d'angle"},{"libelle":"Repère 5","reponse":"L'aile du roi"},{"libelle":"Repère 6","reponse":"La chapelle"}],"etiquettes":["Le donjon","L'escalier à double révolution","Les salles en croix","Une tour d'angle","L'aile du roi","La chapelle","La herse"],"consigne":"Observe le plan de Chambord vu de dessus. Place chaque étiquette dans la case du bon repère (1 à 6). Une étiquette est en trop.<svg viewBox=\"0 0 340 240\" role=\"img\" aria-label=\"Plan schématique du château de Chambord vu de dessus, avec des repères numérotés\" style=\"display:block;max-width:440px;margin:10px auto;background:#eef2df;border:2px solid #8a7a5a;border-radius:10px\">\n<rect x=\"14\" y=\"20\" width=\"312\" height=\"208\" rx=\"18\" fill=\"#9cc3d8\" stroke=\"#4d7489\"/>\n<rect x=\"40\" y=\"48\" width=\"260\" height=\"154\" fill=\"#e6dcc4\" stroke=\"#6e6452\" stroke-width=\"5\"/>\n<g fill=\"#cfc2a3\" stroke=\"#6e6452\" stroke-width=\"3\"><circle cx=\"40\" cy=\"48\" r=\"20\"/><circle cx=\"300\" cy=\"48\" r=\"20\"/><circle cx=\"40\" cy=\"202\" r=\"16\"/><circle cx=\"300\" cy=\"202\" r=\"16\"/></g>\n<rect x=\"118\" y=\"28\" width=\"104\" height=\"104\" fill=\"#d9ccb0\" stroke=\"#3d352b\" stroke-width=\"3\"/>\n<g fill=\"#cfc2a3\" stroke=\"#3d352b\" stroke-width=\"2.5\"><circle cx=\"118\" cy=\"28\" r=\"14\"/><circle cx=\"222\" cy=\"28\" r=\"14\"/><circle cx=\"118\" cy=\"132\" r=\"14\"/><circle cx=\"222\" cy=\"132\" r=\"14\"/></g>\n<g fill=\"#f3ead6\" stroke=\"#8a7a5a\"><rect x=\"161\" y=\"34\" width=\"18\" height=\"92\"/><rect x=\"124\" y=\"71\" width=\"92\" height=\"18\"/></g>\n<circle cx=\"170\" cy=\"80\" r=\"9\" fill=\"#b98a3e\" stroke=\"#5e3f1f\" stroke-width=\"1.5\"/><path d=\"M170 72 A8 8 0 0 1 178 80 M170 88 A8 8 0 0 1 162 80\" stroke=\"#5e3f1f\" fill=\"none\"/>\n<text x=\"170\" y=\"222\" font-size=\"9\" text-anchor=\"middle\" font-family=\"Georgia,serif\" fill=\"#2b1d10\">schéma simplifié, sans échelle</text>\n<g font-family=\"Georgia,serif\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#2b1d10\"><circle cx=\"150\" cy=\"50\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"150\" y=\"55\">1</text><circle cx=\"170\" cy=\"92\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"170\" y=\"97\">2</text><circle cx=\"205\" cy=\"70\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"205\" y=\"75\">3</text><circle cx=\"46\" cy=\"198\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"46\" y=\"203\">4</text><circle cx=\"292\" cy=\"54\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"292\" y=\"59\">5</text><circle cx=\"46\" cy=\"54\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"46\" y=\"59\">6</text></g>\n</svg>","indices":["Les salles en croix partent de l'escalier.","Le donjon de Chambord n'a pas de herse : c'est un palais.","Les appartements du roi sont dans l'aile opposée à la chapelle."],"dialogue":"Bonjour ! Je m'appelle Colombe, mon père est maître maçon. Ici, on dessine les châteaux du roi. Ce ne sont plus des forteresses : on veut de grandes fenêtres, des escaliers magnifiques, tout bien symétrique, comme dans l'Antiquité. Le roi rêve d'un château encore plus grand, à Chambord. Lisez les plans avec moi, et je vous donne la page."}},{"id":"e4-2","escale":4,"ordre":2,"titre":"Château fort ou château Renaissance ?","decor":"plans","objet_principal":"objet-2","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"bastien","probleme_narratif":"Bastien trie les caractéristiques de chaque château.","enjeu":"Les confondre, c'est mal dater un château.","episode_du_roman":"Académie de Nice, fiches « Le château fort » et « Le château de Chambord » (EAC) ; Château royal de Blois","competence_programme":"Comparer château fort et château de la Renaissance","pourquoi_ce_savoir_ici":"La salle « Le cabinet des plans — Les châteaux de la Renaissance » repose sur cette notion.","reaction_du_decor":{"effet":"eclat","description":"Les deux maquettes tournent."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"chateaux-renaissance","type":"tri","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"Le château fort est d'abord fait pour se défendre : murs épais, meurtrières, pont-levis, herse. Le château de la Renaissance est fait pour vivre et pour montrer la puissance du roi : grandes fenêtres, symétrie, décor sculpté, escaliers monumentaux, jardins. Il garde parfois des tours et un donjon, mais ils servent surtout de décor et de logement.","matelot":{"colonnes":[{"id":"fort","titre":"Château fort"},{"id":"renaissance","titre":"Château de la Renaissance"}],"cartes":[{"txt":"Des meurtrières pour tirer","col":"fort"},{"txt":"Un pont-levis et une herse","col":"fort"},{"txt":"Des murs très épais","col":"fort"},{"txt":"De grandes fenêtres","col":"renaissance"},{"txt":"Des jardins pour se promener","col":"renaissance"},{"txt":"Des salamandres sculptées","col":"renaissance"}],"consigne":"Range chaque élément : château fort du Moyen Âge, ou château de la Renaissance ? Clique sur une carte, puis sur une colonne.","indices":["Les grandes fenêtres laissent entrer la lumière : on ne se défend plus.","Les meurtrières servent à tirer.","Trois cartes par colonne."],"dialogue":"Château fort ou château Renaissance ? Triez."},"timonier":{"colonnes":[{"id":"fort","titre":"Château fort"},{"id":"renaissance","titre":"Château de la Renaissance"},{"id":"deux","titre":"Les deux"}],"cartes":[{"txt":"Des meurtrières pour tirer","col":"fort"},{"txt":"Un pont-levis et une herse","col":"fort"},{"txt":"Des murs faits pour résister aux assauts","col":"fort"},{"txt":"Une façade symétrique","col":"renaissance"},{"txt":"Un escalier monumental décoré","col":"renaissance"},{"txt":"De grandes fenêtres et des lucarnes sculptées","col":"renaissance"},{"txt":"Des tours rondes","col":"deux"},{"txt":"Un donjon","col":"deux"}],"consigne":"Range chaque élément : château fort, château de la Renaissance, ou les deux. Attention aux pièges.","indices":["Chambord a un donjon et des tours, comme un château fort.","La symétrie vient de l'Antiquité.","La herse et le pont-levis : pour se défendre."],"dialogue":"Château fort ou château Renaissance ? Triez."}},{"id":"e4-3","escale":4,"ordre":3,"titre":"Trois châteaux, trois secrets","decor":"plans","objet_principal":"objet-3","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"tommaso","probleme_narratif":"Tommaso associe chaque château à son secret.","enjeu":"Sans les secrets, on ne reconnaît pas les châteaux.","episode_du_roman":"Château royal d'Amboise (notice de visite 2026) ; Château royal de Blois ; Académie de Nice, fiche « Le château de Chambord » ; Vikidia, « F","competence_programme":"Comparer château fort et château de la Renaissance","pourquoi_ce_savoir_ici":"La salle « Le cabinet des plans — Les châteaux de la Renaissance » repose sur cette notion.","reaction_du_decor":{"effet":"calme","description":"Les trois châteaux s'illuminent."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"chateaux-renaissance","type":"association","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"Amboise : François Ier y passe son enfance et Léonard y repose (chapelle Saint-Hubert). Blois : l'aile François Ier et son grand escalier à vis sculpté. Chambord : commencé en 1519, célèbre pour son escalier à double révolution. Le Clos Lucé (le manoir du Cloux) : la maison où Léonard vécut ses dernières années. Fontainebleau : des artistes italiens y décorent le château du roi.","matelot":{"paires":[{"g":"Amboise","d":"le roi y a passé son enfance"},{"g":"Blois","d":"un grand escalier à vis sur la façade"},{"g":"Chambord","d":"un escalier à double révolution"}],"consigne":"Relie chaque château à ce qui le rend célèbre : clique sur un château, puis sur la bonne étiquette.","indices":["Tu es à Amboise : c'est là que le roi a grandi.","L'escalier à double révolution est à Chambord.","Blois a un grand escalier à vis sur sa façade."],"dialogue":"Trois châteaux, trois secrets. Associez-les."},"timonier":{"paires":[{"g":"Amboise","d":"Léonard repose dans la chapelle Saint-Hubert"},{"g":"Blois","d":"l'aile François Ier et son escalier à vis sculpté"},{"g":"Chambord","d":"commencé en 1519, escalier à double révolution"},{"g":"Le Clos Lucé","d":"le manoir où Léonard vécut ses dernières années"},{"g":"Fontainebleau","d":"des artistes italiens y décorent le château"}],"consigne":"Relie chaque lieu à ce qui le rend célèbre.","indices":["Le Clos Lucé est l'ancien manoir du Cloux.","Le Primatice travaille à Fontainebleau.","Léonard repose dans la chapelle Saint-Hubert."],"dialogue":"Trois châteaux, trois secrets. Associez-les."}},{"id":"e4-4","escale":4,"ordre":4,"titre":"La salamandre a-t-elle raison ?","decor":"plans","objet_principal":"objet-4","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"jacquet","probleme_narratif":"Jacquet demande si la salamandre a raison.","enjeu":"Croire la salamandre, c'est se tromper de roi.","episode_du_roman":"Académie de Nice, fiche « Le château de Chambord » (EAC) ; Vikidia, « Château de Chambord » ; Château royal d'Amboise","competence_programme":"Comparer château fort et château de la Renaissance","pourquoi_ce_savoir_ici":"La salle « Le cabinet des plans — Les châteaux de la Renaissance » repose sur cette notion.","reaction_du_decor":{"effet":"carte","description":"La salamandre scintille."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"chateaux-renaissance","type":"vraifaux","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"La salamandre est l'emblème de François Ier ; on la voit partout à Chambord, avec la lettre F et la couronne. Sa devise latine est « Nutrisco et extinguo ». Chambord est commencé en 1519, l'année de la mort de Léonard : il n'a donc pas vu le château. On pense que l'escalier à double révolution s'inspire de ses idées, mais personne n'en est sûr. Le château compte plus de 400 pièces.","niveaux":["timonier"],"timonier":{"affirmations":[{"txt":"La salamandre est l'emblème de François Ier.","vrai":true,"explication":"On la voit sculptée partout à Chambord, à Blois, à Fontainebleau."},{"txt":"La devise du roi, en latin, est « Nutrisco et extinguo ».","vrai":true,"explication":"« Je m'en nourris et je l'éteins » : la salamandre résisterait au feu."},{"txt":"Léonard de Vinci a vu Chambord terminé.","vrai":false,"explication":"Le chantier commence en 1519, l'année de sa mort, et dure des dizaines d'années."},{"txt":"On est certain que Léonard a dessiné l'escalier à double révolution.","vrai":false,"explication":"C'est possible, mais aucun document ne le prouve."},{"txt":"Chambord compte plus de 400 pièces.","vrai":true,"explication":"Et environ 80 escaliers et 300 cheminées."},{"txt":"La façade de Chambord est construite selon les règles de la symétrie.","vrai":true,"explication":"La symétrie est une idée héritée de l'Antiquité."}],"consigne":"Colombe a noté six phrases sur Chambord et la salamandre. Pour chacune, réponds « Vrai » ou « Faux », puis vérifie.","indices":["Léonard meurt le 2 mai 1519 ; le chantier commence la même année.","Pour l'escalier, les historiens disent « probablement ».","Compte : plus de 400 pièces, environ 80 escaliers."],"dialogue":"La salamandre a-t-elle raison ? Vrai ou faux."}}]},{"numero":5,"id":"la-galerie-des-tableaux-l-art-de-la-renaissance","titre":"La galerie des tableaux","lieu":"La galerie des tableaux du château","matiere":"","periode_conseillee":"","episode":"Des tableaux venus d'Italie : des portraits, des paysages, des palais peints si profonds qu'on croirait pouvoir y entrer.","scenarimage":"","mot":"PERSPECTIVE","mot_origine":"Le mot-clé de la salle 5.","air":null,"cinematique_ouverture":"transition-e5","cinematique_fin":"fin-e5","etats_decor":[],"enigmes":[{"id":"e5-1","escale":5,"ordre":1,"titre":"Lire un tableau en perspective","decor":"galerie","objet_principal":"objet-1","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"bastien","probleme_narratif":"Bastien montre comment lire la perspective.","enjeu":"Sans lire le tableau, on ne voit pas la profondeur.","episode_du_roman":"Encyclopédie Larousse, « perspective » ; Musée du Louvre, ressources pédagogiques ; tableau schématique dessiné pour le jeu","competence_programme":"Expliquer la perspective","pourquoi_ce_savoir_ici":"La salle « La galerie des tableaux — L'art de la Renaissance » repose sur cette notion.","reaction_du_decor":{"effet":"eclat","description":"Les lignes de fuite se dessinent."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"art-renaissance","type":"plan","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"Dans un tableau en perspective, toutes les lignes qui s'enfoncent (lignes de fuite) se rejoignent en un point, le point de fuite, placé sur la ligne d'horizon. Ce qui est proche (au premier plan) est grand ; ce qui est loin (à l'arrière-plan) est petit. Les peintres de la Renaissance utilisent ces règles pour donner l'illusion de la profondeur.","matelot":{"titre":"Le tableau de Bastien","colonnes":2,"cases":[{"libelle":"Repère 1 — là où toutes les lignes se rejoignent","reponse":"Le point de fuite"},{"libelle":"Repère 2 — la ligne en pointillés","reponse":"La ligne d'horizon"},{"libelle":"Repère 3 — tout près, en bas","reponse":"Le premier plan"},{"libelle":"Repère 4 — tout au fond","reponse":"L'arrière-plan"}],"consigne":"Bastien a peint un tableau en perspective. Clique sur une étiquette, puis sur la case du bon repère.<svg viewBox=\"0 0 340 220\" role=\"img\" aria-label=\"Un tableau construit en perspective, avec des repères numérotés\" style=\"display:block;max-width:440px;margin:10px auto;background:#fbf3dd;border:6px solid #b8860b;border-radius:4px\">\n<rect width=\"340\" height=\"92\" fill=\"#cfe2ef\"/><rect y=\"92\" width=\"340\" height=\"128\" fill=\"#e8d9b6\"/>\n<line x1=\"10\" y1=\"210\" x2=\"170\" y2=\"92\" stroke=\"#7a6a4a\" stroke-width=\"1\"/><line x1=\"50\" y1=\"210\" x2=\"170\" y2=\"92\" stroke=\"#7a6a4a\" stroke-width=\"1\"/><line x1=\"90\" y1=\"210\" x2=\"170\" y2=\"92\" stroke=\"#7a6a4a\" stroke-width=\"1\"/><line x1=\"130\" y1=\"210\" x2=\"170\" y2=\"92\" stroke=\"#7a6a4a\" stroke-width=\"1\"/><line x1=\"170\" y1=\"210\" x2=\"170\" y2=\"92\" stroke=\"#7a6a4a\" stroke-width=\"1\"/><line x1=\"210\" y1=\"210\" x2=\"170\" y2=\"92\" stroke=\"#7a6a4a\" stroke-width=\"1\"/><line x1=\"250\" y1=\"210\" x2=\"170\" y2=\"92\" stroke=\"#7a6a4a\" stroke-width=\"1\"/><line x1=\"290\" y1=\"210\" x2=\"170\" y2=\"92\" stroke=\"#7a6a4a\" stroke-width=\"1\"/><line x1=\"330\" y1=\"210\" x2=\"170\" y2=\"92\" stroke=\"#7a6a4a\" stroke-width=\"1\"/><g stroke=\"#7a6a4a\" stroke-width=\"1\"><line x1=\"158\" y1=\"100\" x2=\"181\" y2=\"100\"/><line x1=\"141\" y1=\"112\" x2=\"198\" y2=\"112\"/><line x1=\"115\" y1=\"130\" x2=\"224\" y2=\"130\"/><line x1=\"72\" y1=\"160\" x2=\"267\" y2=\"160\"/><line x1=\"14\" y1=\"200\" x2=\"325\" y2=\"200\"/></g>\n<g fill=\"#d9cdb2\" stroke=\"#6e6452\"><path d=\"M0 20 L120 76 L120 140 L0 210 Z\"/><path d=\"M340 20 L220 76 L220 140 L340 210 Z\"/></g>\n<g fill=\"#efe6cf\" stroke=\"#6e6452\"><rect x=\"14\" y=\"30\" width=\"6\" height=\"175\"/><rect x=\"54\" y=\"48\" width=\"6\" height=\"133\"/><rect x=\"92\" y=\"66\" width=\"6\" height=\"93\"/></g>\n<line x1=\"0\" y1=\"92\" x2=\"340\" y2=\"92\" stroke=\"#8a2626\" stroke-width=\"1.5\" stroke-dasharray=\"6 4\"/>\n<circle cx=\"170\" cy=\"92\" r=\"3\" fill=\"#8a2626\"/>\n<g fill=\"#3d5266\"><rect x=\"100\" y=\"150\" width=\"30\" height=\"58\" rx=\"8\"/><circle cx=\"115\" cy=\"140\" r=\"11\" fill=\"#e9c49e\"/></g>\n<g fill=\"#7a2a3a\"><rect x=\"190\" y=\"104\" width=\"8\" height=\"15\" rx=\"2\"/><circle cx=\"194\" cy=\"101\" r=\"3\" fill=\"#e9c49e\"/></g>\n<g fill=\"#9cb7cc\"><path d=\"M150 40 l20 -14 l20 14 Z\" fill=\"#8a7a5a\"/><rect x=\"152\" y=\"40\" width=\"36\" height=\"30\" fill=\"#efe3c8\" stroke=\"#8a7a5a\"/></g>\n<g font-family=\"Georgia,serif\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#2b1d10\"><circle cx=\"170\" cy=\"92\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"170\" y=\"97\">1</text><circle cx=\"24\" cy=\"92\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"24\" y=\"97\">2</text><circle cx=\"60\" cy=\"196\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"60\" y=\"201\">3</text><circle cx=\"208\" cy=\"46\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"208\" y=\"51\">4</text></g>\n</svg>","indices":["Toutes les lignes du dallage vont vers le repère 1.","La ligne pointillée rouge, c'est l'horizon.","Le premier plan est tout près de nous, en bas."],"dialogue":"Ah, la dernière page ! Je l'étudiais, car je veux peindre comme les Italiens. Regardez ces tableaux : on dirait des fenêtres ouvertes sur le monde. Le secret, ce sont des règles de dessin. Les corps aussi ont leurs règles. Prouvez-moi que vous savez lire un tableau, et la page est à vous."},"timonier":{"titre":"Le tableau de Bastien","colonnes":3,"cases":[{"libelle":"Repère 1","reponse":"Le point de fuite"},{"libelle":"Repère 2","reponse":"La ligne d'horizon"},{"libelle":"Repère 3","reponse":"Le premier plan"},{"libelle":"Repère 4","reponse":"L'arrière-plan"},{"libelle":"Repère 5","reponse":"Une ligne de fuite"},{"libelle":"Repère 6","reponse":"Un personnage au loin"}],"etiquettes":["Le point de fuite","La ligne d'horizon","Le premier plan","L'arrière-plan","Une ligne de fuite","Un personnage au loin","Le cadre doré"],"consigne":"Observe ce tableau construit en perspective. Place chaque étiquette dans la case du bon repère (1 à 6). Une étiquette est en trop.<svg viewBox=\"0 0 340 220\" role=\"img\" aria-label=\"Un tableau construit en perspective, avec des repères numérotés\" style=\"display:block;max-width:440px;margin:10px auto;background:#fbf3dd;border:6px solid #b8860b;border-radius:4px\">\n<rect width=\"340\" height=\"92\" fill=\"#cfe2ef\"/><rect y=\"92\" width=\"340\" height=\"128\" fill=\"#e8d9b6\"/>\n<line x1=\"10\" y1=\"210\" x2=\"170\" y2=\"92\" stroke=\"#7a6a4a\" stroke-width=\"1\"/><line x1=\"50\" y1=\"210\" x2=\"170\" y2=\"92\" stroke=\"#7a6a4a\" stroke-width=\"1\"/><line x1=\"90\" y1=\"210\" x2=\"170\" y2=\"92\" stroke=\"#7a6a4a\" stroke-width=\"1\"/><line x1=\"130\" y1=\"210\" x2=\"170\" y2=\"92\" stroke=\"#7a6a4a\" stroke-width=\"1\"/><line x1=\"170\" y1=\"210\" x2=\"170\" y2=\"92\" stroke=\"#7a6a4a\" stroke-width=\"1\"/><line x1=\"210\" y1=\"210\" x2=\"170\" y2=\"92\" stroke=\"#7a6a4a\" stroke-width=\"1\"/><line x1=\"250\" y1=\"210\" x2=\"170\" y2=\"92\" stroke=\"#7a6a4a\" stroke-width=\"1\"/><line x1=\"290\" y1=\"210\" x2=\"170\" y2=\"92\" stroke=\"#7a6a4a\" stroke-width=\"1\"/><line x1=\"330\" y1=\"210\" x2=\"170\" y2=\"92\" stroke=\"#7a6a4a\" stroke-width=\"1\"/><g stroke=\"#7a6a4a\" stroke-width=\"1\"><line x1=\"158\" y1=\"100\" x2=\"181\" y2=\"100\"/><line x1=\"141\" y1=\"112\" x2=\"198\" y2=\"112\"/><line x1=\"115\" y1=\"130\" x2=\"224\" y2=\"130\"/><line x1=\"72\" y1=\"160\" x2=\"267\" y2=\"160\"/><line x1=\"14\" y1=\"200\" x2=\"325\" y2=\"200\"/></g>\n<g fill=\"#d9cdb2\" stroke=\"#6e6452\"><path d=\"M0 20 L120 76 L120 140 L0 210 Z\"/><path d=\"M340 20 L220 76 L220 140 L340 210 Z\"/></g>\n<g fill=\"#efe6cf\" stroke=\"#6e6452\"><rect x=\"14\" y=\"30\" width=\"6\" height=\"175\"/><rect x=\"54\" y=\"48\" width=\"6\" height=\"133\"/><rect x=\"92\" y=\"66\" width=\"6\" height=\"93\"/></g>\n<line x1=\"0\" y1=\"92\" x2=\"340\" y2=\"92\" stroke=\"#8a2626\" stroke-width=\"1.5\" stroke-dasharray=\"6 4\"/>\n<circle cx=\"170\" cy=\"92\" r=\"3\" fill=\"#8a2626\"/>\n<g fill=\"#3d5266\"><rect x=\"100\" y=\"150\" width=\"30\" height=\"58\" rx=\"8\"/><circle cx=\"115\" cy=\"140\" r=\"11\" fill=\"#e9c49e\"/></g>\n<g fill=\"#7a2a3a\"><rect x=\"190\" y=\"104\" width=\"8\" height=\"15\" rx=\"2\"/><circle cx=\"194\" cy=\"101\" r=\"3\" fill=\"#e9c49e\"/></g>\n<g fill=\"#9cb7cc\"><path d=\"M150 40 l20 -14 l20 14 Z\" fill=\"#8a7a5a\"/><rect x=\"152\" y=\"40\" width=\"36\" height=\"30\" fill=\"#efe3c8\" stroke=\"#8a7a5a\"/></g>\n<g font-family=\"Georgia,serif\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#2b1d10\"><circle cx=\"170\" cy=\"92\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"170\" y=\"97\">1</text><circle cx=\"24\" cy=\"92\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"24\" y=\"97\">2</text><circle cx=\"60\" cy=\"196\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"60\" y=\"201\">3</text><circle cx=\"208\" cy=\"46\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"208\" y=\"51\">4</text><circle cx=\"262\" cy=\"180\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"262\" y=\"185\">5</text><circle cx=\"216\" cy=\"114\" r=\"10\" fill=\"#fff\" stroke=\"#3d2b14\" stroke-width=\"1.5\"/><text x=\"216\" y=\"119\">6</text></g>\n</svg>","indices":["Les lignes du dallage sont des lignes de fuite.","Plus un personnage est loin, plus il est petit.","Le cadre n'a pas de numéro."],"dialogue":"Ah, la dernière page ! Je l'étudiais, car je veux peindre comme les Italiens. Regardez ces tableaux : on dirait des fenêtres ouvertes sur le monde. Le secret, ce sont des règles de dessin. Les corps aussi ont leurs règles. Prouvez-moi que vous savez lire un tableau, et la page est à vous."}},{"id":"e5-2","escale":5,"ordre":2,"titre":"Les secrets des peintres","decor":"galerie","objet_principal":"objet-2","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"tommaso","probleme_narratif":"Tommaso interroge sur les secrets des peintres.","enjeu":"Sans les secrets, la perspective reste un mystère.","episode_du_roman":"Vikidia, « Homme de Vitruve » ; Encyclopædia Universalis, « La Joconde » ; Musée du Louvre","competence_programme":"Expliquer la perspective","pourquoi_ce_savoir_ici":"La salle « La galerie des tableaux — L'art de la Renaissance » repose sur cette notion.","reaction_du_decor":{"effet":"calme","description":"Les couleurs du tableau s'approfondissent."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"art-renaissance","type":"qcm","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"Les peintres de la Renaissance représentent le monde comme on le voit : perspective, proportions du corps, portraits ressemblants. L'Homme de Vitruve (vers 1490) inscrit un corps humain dans un cercle et un carré. La Joconde, portrait de Lisa Gherardini, est peinte avec le sfumato, un léger flou qui adoucit les contours ; elle est au musée du Louvre.","matelot":{"questions":[{"q":"Pourquoi les personnages au fond d'un tableau sont-ils plus petits ?","options":["pour montrer qu'ils sont loin : c'est la perspective","parce que ce sont des enfants","parce que le peintre manquait de place"],"bonne":0,"explication":"La perspective donne l'illusion de la profondeur."},{"q":"Que montre l'Homme de Vitruve de Léonard ?","options":["les proportions du corps, dans un cercle et un carré","un roi sur son cheval","une machine volante"],"bonne":0,"explication":"Un dessin fait vers 1490."},{"q":"La Joconde est…","options":["un portrait","un paysage sans personne","une statue"],"bonne":0,"explication":"Le portrait d'une Florentine, Lisa Gherardini."}],"consigne":"Réponds aux trois questions, puis clique sur « Vérifier ».","indices":["Ce qui est loin paraît plus petit.","L'Homme de Vitruve tient dans deux figures géométriques.","Un portrait représente une personne."],"dialogue":"Les peintres ont leurs secrets. Répondez aux questions."},"timonier":{"questions":[{"q":"Qu'est-ce que le sfumato ?","options":["un léger flou qui adoucit les contours","une couleur bleue très chère","un cadre doré","une sculpture en marbre"],"bonne":0,"explication":"Léonard l'utilise dans la Joconde."},{"q":"D'après qui Léonard dessine-t-il l'Homme de Vitruve ?","options":["Vitruve, un architecte romain de l'Antiquité","François Ier","Gutenberg","Michel-Ange"],"bonne":0,"explication":"Encore l'Antiquité comme modèle."},{"q":"Où peut-on voir la Joconde aujourd'hui ?","options":["au musée du Louvre, à Paris","au château d'Amboise","à Florence","à Chambord"],"bonne":0,"explication":"Elle est entrée dans les collections du roi, puis au Louvre."},{"q":"Quel est le point commun des artistes de la Renaissance ?","options":["représenter le monde et le corps humain de façon réaliste, avec des règles","peindre seulement des fonds dorés","refuser l'Antiquité","ne jamais signer"],"bonne":0,"explication":"Perspective, proportions, observation."}],"consigne":"Réponds aux quatre questions, puis vérifie. Une seule réponse est exacte à chaque fois.","indices":["Sfumato vient d'un mot italien qui évoque la fumée.","Vitruve était un architecte romain.","La Joconde est à Paris."],"dialogue":"Les peintres ont leurs secrets. Répondez aux questions."}},{"id":"e5-3","escale":5,"ordre":3,"titre":"Le cadenas du carnet","decor":"galerie","objet_principal":"objet-3","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"jacquet","probleme_narratif":"Jacquet cherche le code du carnet.","enjeu":"Sans le code, le carnet reste fermé.","episode_du_roman":"Château royal d'Amboise ; Encyclopædia Universalis, « La Joconde » ; Académie de Nice, fiche « Le château de Chambord »","competence_programme":"Expliquer la perspective","pourquoi_ce_savoir_ici":"La salle « La galerie des tableaux — L'art de la Renaissance » repose sur cette notion.","reaction_du_decor":{"effet":"carte","description":"Le cadenas s'ouvre."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"art-renaissance","type":"code","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"François Ier devient roi en 1515 et invite Léonard de Vinci. Son emblème est la salamandre. Léonard meurt à Amboise en 1519 ; la Joconde est aujourd'hui au Louvre. La devise du roi commence par « Nutrisco ».","matelot":{"champs":[{"libelle":"Année où François Ier devient roi","valeur":"1515","longueur":4},{"libelle":"Le prénom de l'artiste invité (7 lettres)","valeur":"LEONARD","longueur":7,"numerique":false},{"libelle":"L'emblème du roi (10 lettres)","valeur":"SALAMANDRE","longueur":10,"numerique":false}],"consigne":"La dernière page du carnet est fermée par un cadenas. Écris l'année, le prénom et l'emblème demandés (les accents ne comptent pas), puis ouvre.","indices":["L'année de Marignan.","Le prénom de l'artiste invité : L… (7 lettres).","L'animal sculpté partout à Chambord."],"dialogue":"Le carnet est fermé par un cadenas. Trouvez le code."},"timonier":{"champs":[{"libelle":"Année de la mort de Léonard","valeur":"1519","longueur":4},{"libelle":"Le musée où se trouve la Joconde (6 lettres)","valeur":"LOUVRE","longueur":6,"numerique":false},{"libelle":"Premier mot de la devise latine du roi (8 lettres)","valeur":"NUTRISCO","longueur":8,"numerique":false}],"consigne":"La dernière page du carnet est fermée par un cadenas à trois cases. Écris l'année, le musée et le premier mot de la devise du roi, puis ouvre.","indices":["Léonard meurt le 2 mai de cette année.","Le grand musée de Paris.","« … et extinguo »."],"dialogue":"Le carnet est fermé par un cadenas. Trouvez le code."}},{"id":"e5-4","escale":5,"ordre":4,"titre":"La leçon de Bastien","decor":"galerie","objet_principal":"objet-4","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"helene","probleme_narratif":"Hélène complète la leçon de Bastien.","enjeu":"Sans cette dernière réponse, la galerie reste fermée.","episode_du_roman":"Encyclopédie Larousse, « perspective » ; Vikidia, « Homme de Vitruve » ; Encyclopædia Universalis, « La Joconde »","competence_programme":"Expliquer la perspective","pourquoi_ce_savoir_ici":"La salle « La galerie des tableaux — L'art de la Renaissance » repose sur cette notion.","reaction_du_decor":{"effet":"ouverture","description":"La galerie s'illumine : tous les mots sont trouvés."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"art-renaissance","type":"trous","niveau_variantes":"Données du jeu d'origine (CM1 / CM2).","correction_origine":"Les artistes de la Renaissance cherchent à représenter le monde de façon réaliste : la perspective crée la profondeur, l'étude des proportions donne des corps justes, le portrait montre une personne ressemblante. Ils prennent l'Antiquité pour modèle.","niveaux":["timonier"],"timonier":{"texte":"<p>Pour donner de la profondeur, le peintre trace des lignes qui se rejoignent au point de [[fuite]], sur la ligne d'[[horizon]]. Ce qui est loin est dessiné plus [[petit]]. Léonard étudie les [[proportions]] du corps humain. Dans la Joconde, un [[portrait]], il adoucit les contours grâce au [[sfumato]].</p>","etiquettes":["fuite","horizon","petit","proportions","portrait","sfumato","grand","salamandre","vitrail","paysan"],"consigne":"Complète la leçon de Bastien. Clique sur une étiquette, puis sur le trou où elle va. Quatre étiquettes sont en trop.","indices":["Les lignes se rejoignent au point de…","L'Homme de Vitruve étudie les… du corps.","La Joconde est un…"],"dialogue":"Dernière étape : complétez la leçon de Bastien sur la perspective."}}]}]},"lecons":{"rayons":[{"id":"lecons","titre":"Rayon des leçons","icone":"📖"}],"lecons":[{"id":"renaissance-humanisme","rayon":"lecons","fiche":1,"icone":"📖","titre":"La Renaissance et l'humanisme","escale":1,"competence":"Expliquer le mot Renaissance ; Dire d'où vient la Renaissance ; Comprendre le rôle de l'imprimerie et des humanistes","essentiel":"<h4>Un temps nouveau</h4><p>Au XVe siècle, en <b>Italie</b>, des artistes et des savants admirent l'art et les livres de l'<b>Antiquité</b>, l'époque des Grecs et des Romains. Ils veulent les faire « renaître » : c'est la <b>Renaissance</b>.</p><p>Les architectes imitent les colonnes des temples antiques ; les peintres et les sculpteurs étudient le corps humain.</p><h4>L'imprimerie</h4><p>Vers <b>1450</b>, <b>Gutenberg</b> met au point l'<b>imprimerie</b>. Avant, chaque livre était recopié à la main. Désormais, on fabrique beaucoup de livres, plus vite et moins cher : les idées circulent dans toute l'Europe.</p><div class='encadre'>La Renaissance arrive en France avec les rois qui reviennent des guerres d'Italie, puis avec <b>François Ier</b>, roi en <b>1515</b>.</div>","approfondi":"<h4>Faire renaître l'Antiquité</h4><p>La <b>Renaissance</b> commence en <b>Italie</b>, à Florence, au XVe siècle, puis gagne l'Europe au XVIe siècle. Artistes et savants prennent l'<b>Antiquité</b> grecque et romaine pour modèle : colonnes, symétrie, statues, textes anciens.</p><h4>Les humanistes</h4><p>Les <b>humanistes</b> apprennent le latin, le grec et l'hébreu pour lire les textes anciens dans leur langue. Ils pensent que l'homme peut progresser grâce au savoir. En France, Guillaume <b>Budé</b>, conseiller de François Ier, est l'un d'eux.</p><h4>Une révolution du livre</h4><p>Vers <b>1450</b>, à Mayence, <b>Gutenberg</b> met au point l'imprimerie à <b>caractères mobiles</b> : des lettres de métal que l'on assemble, encre et presse. Un même texte est tiré en centaines d'exemplaires et circule dans toute l'Europe.</p><div class='encadre'>Dès <b>1496</b>, le roi Charles VIII revient d'Italie avec des artistes italiens et fait aménager Amboise. François Ier, roi en <b>1515</b>, va plus loin encore.</div><table class='tab-lecon'><tr><th>Mot</th><th>Définition</th></tr><tr><td><b>Renaissance</b></td><td>époque (XVe-XVIe siècles) où l'on redécouvre l'art et les savoirs de l'Antiquité</td></tr><tr><td><b>Antiquité</b></td><td>époque des Grecs et des Romains, avant le Moyen Âge</td></tr><tr><td><b>humaniste</b></td><td>savant qui étudie les textes anciens et croit au progrès par le savoir</td></tr><tr><td><b>imprimerie</b></td><td>technique pour reproduire un texte en de nombreux exemplaires</td></tr></table><h4>De l'Antiquité à la Renaissance</h4><table class='tab-lecon'><tr><td>Antiquité</td><td>Grecs et Romains : temples, statues, textes</td></tr><tr><td>Moyen Âge</td><td>Châteaux forts et cathédrales</td></tr><tr><td>vers 1450</td><td>Gutenberg met au point l'imprimerie</td></tr><tr><td>1496</td><td>Charles VIII revient d'Italie avec des artistes</td></tr><tr><td>1515</td><td>François Ier devient roi</td></tr><tr><td>1516</td><td>Léonard de Vinci s'installe à Amboise</td></tr></table>","expert":"<div class='encadre'><b>Les premiers lecteurs royaux</b> — En 1530, sur le conseil de l'humaniste Guillaume Budé, François Ier nomme des « lecteurs royaux » : ils enseignent gratuitement l'hébreu, le grec et les mathématiques. <i>D'après le Collège de France, « Cinq siècles d'histoire ».</i></div>","dans_le_roman":"Voir la salle 1."},{"id":"francois-mecene","rayon":"lecons","fiche":2,"icone":"📖","titre":"François Ier, roi mécène","escale":2,"competence":"Situer le règne de François Ier ; Expliquer le mot mécène ; Dire comment il protège les arts et les lettres","essentiel":"<h4>Un jeune roi</h4><p><b>François Ier</b> passe son enfance au château d'<b>Amboise</b>. Il devient roi en <b>1515</b> et gagne la même année la bataille de <b>Marignan</b>, en Italie. Là-bas, il découvre les œuvres de la Renaissance.</p><h4>Un mécène</h4><p>Un <b>mécène</b> protège, loge et paie des artistes et des savants. François Ier invite en France des artistes italiens, comme <b>Léonard de Vinci</b>. Il fait construire des châteaux magnifiques et achète des tableaux.</p><div class='encadre'>Il protège aussi les <b>lettres</b> : les livres, les savants et la langue française.</div>","approfondi":"<h4>Un roi de la Renaissance</h4><p>Né à Cognac le <b>12 septembre 1494</b>, élevé à Amboise, <b>François Ier</b> devient roi le <b>1er janvier 1515</b>. Les <b>13 et 14 septembre 1515</b>, il remporte la bataille de <b>Marignan</b>, près de Milan. C'est un roi guerrier, qui mène plusieurs guerres en Italie. Là-bas, il découvre les palais, les tableaux et les jardins de la Renaissance italienne, et veut les mêmes en France.</p><h4>Protecteur des arts</h4><p>En mécène, il fait venir des artistes italiens : <b>Léonard de Vinci</b> (1516), plus tard le Primatice et Benvenuto Cellini. Il fait commencer <b>Chambord</b> (1519) et transformer Fontainebleau.</p><h4>Protecteur des lettres</h4><ul><li><b>1530</b> : les <b>lecteurs royaux</b> (futur Collège de France) enseignent gratuitement le grec, l'hébreu, les mathématiques.</li><li><b>1537</b> : le <b>dépôt légal</b> : un exemplaire de chaque livre imprimé va à la bibliothèque du roi.</li><li><b>1539</b> : l'ordonnance de <b>Villers-Cotterêts</b> impose le <b>français</b> dans les actes de justice et d'administration.</li></ul><div class='encadre'>Un mécène ne crée pas lui-même les œuvres : il choisit, protège et paie ceux qui les créent. Léonard est l'artiste ; François Ier est le roi qui l'accueille.</div><table class='tab-lecon'><tr><th>Mot</th><th>Définition</th></tr><tr><td><b>mécène</b></td><td>personne qui protège et aide les artistes et les savants</td></tr><tr><td><b>les lettres</b></td><td>les livres, les langues, le savoir</td></tr><tr><td><b>ordonnance</b></td><td>loi décidée par le roi</td></tr><tr><td><b>Marignan</b></td><td>bataille gagnée par François Ier en Italie, en 1515</td></tr></table>","expert":"<div class='encadre'><b>L'ordonnance de Villers-Cotterêts (1539)</b> — Les actes de justice et d'administration du royaume doivent désormais être écrits en « langage maternel français », et non plus en latin. Les curés doivent aussi tenir des registres des baptêmes. <i>D'après Vikidia, « Ordonnance de Villers-Cotterêts » ; texte adapté.</i></div>","dans_le_roman":"Voir la salle 2."},{"id":"leonard-de-vinci","rayon":"lecons","fiche":3,"icone":"📖","titre":"Léonard de Vinci, l'artiste invité","escale":3,"competence":"Présenter Léonard de Vinci ; Distinguer ses talents : peintre, ingénieur, observateur ; Situer ses dernières années à Amboise","essentiel":"<h4>Un génie aux mille talents</h4><p><b>Léonard de Vinci</b> naît en <b>1452</b> à Vinci, en Italie. Il est <b>peintre</b> (la <b>Joconde</b>), <b>ingénieur</b> et <b>inventeur</b> : il dessine des machines, des ponts, des canaux. Il <b>observe</b> tout : les oiseaux, l'eau, les plantes, le corps humain. Il note tout dans des <b>carnets</b>, avec des dessins.</p><div class='encadre'>Attention : beaucoup de ses machines, comme sa machine volante, sont restées des <b>dessins</b>. Elles n'ont jamais été construites à son époque.</div><h4>À Amboise</h4><p>En <b>1516</b>, le roi <b>François Ier</b> l'invite en France. Léonard s'installe au manoir du <b>Cloux</b> (aujourd'hui le Clos Lucé), près du château d'Amboise. Il y meurt en <b>1519</b>.</p>","approfondi":"<h4>Peintre, ingénieur, savant</h4><p>Né le 15 avril <b>1452</b> à Vinci, près de Florence, <b>Léonard</b> se forme dans un atelier de peintre. Il peint des portraits (la <b>Joconde</b>, commencée vers 1503), dessine l'<b>Homme de Vitruve</b> (vers 1490), étudie l'anatomie, le vol des oiseaux, l'eau. Ingénieur, il imagine des machines, des fortifications, des canaux. Ses <b>carnets</b>, des milliers de pages, sont souvent écrits de droite à gauche, comme dans un miroir.</p><div class='encadre'>Ses projets d'inventions (machine volante, char…) sont restés <b>sur le papier</b>. Les maquettes que l'on voit aujourd'hui ont été construites récemment, d'après ses dessins.</div><h4>L'invité du roi</h4><p>En <b>1516</b>, à 64 ans, il arrive à Amboise. François Ier lui donne le manoir du <b>Cloux</b> et le titre de « premier peintre, ingénieur et architecte du roi ». Il a apporté plusieurs tableaux, dont la Joconde, que le roi acquiert. Il meurt au Cloux le <b>2 mai 1519</b> ; il repose aujourd'hui dans la chapelle Saint-Hubert du château.</p><table class='tab-lecon'><tr><th>Mot</th><th>Définition</th></tr><tr><td><b>ingénieur</b></td><td>personne qui invente et conçoit des machines, des ponts, des canaux</td></tr><tr><td><b>carnet</b></td><td>petit cahier où Léonard note ses idées et ses dessins</td></tr><tr><td><b>anatomie</b></td><td>étude du corps humain</td></tr><tr><td><b>Clos Lucé</b></td><td>nom actuel du manoir du Cloux, à Amboise, où Léonard a vécu</td></tr></table><h4>La vie de Léonard</h4><table class='tab-lecon'><tr><td>1452</td><td>Naissance à Vinci, en Italie</td></tr><tr><td>vers 1490</td><td>L'Homme de Vitruve</td></tr><tr><td>vers 1503</td><td>Il commence la Joconde</td></tr><tr><td>1516</td><td>Il s'installe au manoir du Cloux, à Amboise</td></tr><tr><td>2 mai 1519</td><td>Il meurt à Amboise</td></tr></table>","expert":"<div class='encadre'><b>Le titre donné par le roi</b> — En 1516, François Ier confie à Léonard de Vinci le manoir du Cloux, aujourd'hui appelé Clos Lucé, et le nomme « premier peintre, ingénieur et architecte du roi ». <i>D'après le château royal d'Amboise, notice de visite.</i></div>","dans_le_roman":"Voir la salle 3."},{"id":"chateaux-renaissance","rayon":"lecons","fiche":4,"icone":"📖","titre":"Les châteaux de la Renaissance","escale":4,"competence":"Comparer château fort et château de la Renaissance ; Situer Amboise, Blois et Chambord ; Reconnaître l'emblème de François Ier","essentiel":"<h4>Des châteaux pour vivre et briller</h4><p>Au Moyen Âge, le château fort servait surtout à se <b>défendre</b>. À la Renaissance, les rois veulent des châteaux pour <b>vivre</b> et pour montrer leur <b>puissance</b> : grandes fenêtres, décors sculptés, jardins, et des façades <b>symétriques</b>.</p><h4>Trois châteaux de la Loire</h4><ul><li><b>Amboise</b> : le roi y a grandi ; Léonard y repose.</li><li><b>Blois</b> : une aile nouvelle avec un grand escalier à vis.</li><li><b>Chambord</b> : commencé en <b>1519</b>, avec un célèbre <b>escalier à double révolution</b>.</li></ul><div class='encadre'>L'emblème de François Ier est la <b>salamandre</b>. On la voit sculptée partout sur ses châteaux.</div>","approfondi":"<h4>De la défense au prestige</h4><p>Les châteaux de la Renaissance gardent parfois des tours et un donjon, mais ils ne sont plus faits pour soutenir un siège. Ils montrent la richesse et le goût du roi : <b>symétrie</b> héritée de l'Antiquité, grandes fenêtres, lucarnes sculptées, escaliers monumentaux, jardins.</p><h4>Chambord, le rêve du roi</h4><p>Commencé en <b>1519</b> et achevé des dizaines d'années plus tard, Chambord compte plus de <b>400 pièces</b>, environ 80 escaliers et 300 cheminées. Au centre du donjon, l'<b>escalier à double révolution</b> : deux escaliers tournent l'un au-dessus de l'autre, sans jamais se croiser. On pense qu'il s'inspire des idées de Léonard de Vinci, mais rien ne le prouve. Le roi y séjourne peu : c'est surtout un château pour la chasse et pour éblouir ses visiteurs.</p><h4>Amboise et Blois</h4><p>À Amboise, Charles VIII avait déjà fait venir des artistes italiens. À Blois, François Ier fait bâtir une aile nouvelle, avec un grand escalier à vis sculpté.</p><div class='encadre'>La <b>salamandre</b>, emblème de François Ier, porte sa devise latine : « <b>Nutrisco et extinguo</b> », « Je m'en nourris et je l'éteins ». On croyait que cet animal résistait au feu.</div><table class='tab-lecon'><tr><th>Mot</th><th>Définition</th></tr><tr><td><b>symétrie</b></td><td>les deux moitiés d'une façade sont pareilles, de part et d'autre d'un axe</td></tr><tr><td><b>escalier à double révolution</b></td><td>deux escaliers en spirale qui tournent l'un au-dessus de l'autre sans se croiser</td></tr><tr><td><b>emblème</b></td><td>image qui représente une personne (la salamandre pour François Ier)</td></tr><tr><td><b>devise</b></td><td>courte phrase qui accompagne un emblème</td></tr></table>","expert":"<div class='encadre'><b>Chambord en chiffres</b> — Chambord : 156 mètres de façade, plus de 400 pièces, environ 80 escaliers et environ 300 cheminées. Le chantier commence en 1519. <i>D'après la fiche « Le château de Chambord », académie de Nice (éducation artistique et culturelle).</i></div>","dans_le_roman":"Voir la salle 4."},{"id":"art-renaissance","rayon":"lecons","fiche":5,"icone":"📖","titre":"L'art de la Renaissance","escale":5,"competence":"Expliquer la perspective ; Comprendre l'étude des proportions ; Reconnaître un portrait de la Renaissance","essentiel":"<h4>Peindre comme on voit</h4><p>Les peintres de la Renaissance veulent que leurs tableaux ressemblent au monde réel. Ils utilisent la <b>perspective</b> : ce qui est loin est dessiné plus petit, et les lignes qui s'enfoncent se rejoignent en un point, le <b>point de fuite</b>. On croirait regarder par une fenêtre.</p><h4>Le corps humain</h4><p>Ils étudient les <b>proportions</b> du corps. L'<b>Homme de Vitruve</b> de Léonard montre un homme dans un cercle et un carré.</p><div class='encadre'>Ils peignent aussi des <b>portraits</b> très ressemblants, comme la <b>Joconde</b>, aujourd'hui au musée du <b>Louvre</b>.</div>","approfondi":"<h4>La perspective</h4><p>Les lignes qui s'enfoncent dans le tableau, les <b>lignes de fuite</b>, se rejoignent en un <b>point de fuite</b> placé sur la <b>ligne d'horizon</b>. Au <b>premier plan</b>, les objets sont grands ; à l'<b>arrière-plan</b>, ils sont petits. Ces règles de géométrie donnent l'illusion de la profondeur.</p><h4>Les proportions</h4><p>Vers 1490, Léonard dessine l'<b>Homme de Vitruve</b>, d'après les écrits de Vitruve, un architecte romain : un corps humain inscrit dans un cercle et un carré. Il est conservé à Venise. Les artistes mesurent, comparent, dessinent des modèles vivants : l'art devient aussi une science.</p><h4>Le portrait</h4><p>La <b>Joconde</b>, portrait de la Florentine Lisa Gherardini, est peinte à l'huile sur bois. Léonard y utilise le <b>sfumato</b>, un léger flou qui adoucit les contours. Entrée dans les collections du roi, elle est aujourd'hui au musée du <b>Louvre</b>, où des millions de visiteurs viennent la voir chaque année.</p><table class='tab-lecon'><tr><th>Mot</th><th>Définition</th></tr><tr><td><b>perspective</b></td><td>règles de dessin qui donnent l'illusion de la profondeur</td></tr><tr><td><b>point de fuite</b></td><td>point où se rejoignent les lignes de fuite, sur la ligne d'horizon</td></tr><tr><td><b>proportions</b></td><td>rapports de taille entre les parties du corps</td></tr><tr><td><b>sfumato</b></td><td>léger flou qui adoucit les contours</td></tr></table>","expert":"<div class='encadre'><b>La Joconde</b> — Portrait de Lisa Gherardini, épouse d'un marchand florentin. Huile sur un panneau de bois de peuplier, 77 cm sur 53 cm. Léonard l'apporte en France ; le roi l'acquiert après sa mort. <i>D'après l'Encyclopædia Universalis, « La Joconde » ; Musée du Louvre.</i></div>","dans_le_roman":"Voir la salle 5."}]},"decors-fx":{"decors":{"imprimerie":{"titre":"Une imprimerie de la ville d'Amboise, au printemps 1518","reference":null,"ambiance":["vent"],"kenBurns":{"echelle":1.05,"duree":32},"effets":[{"type":"lueur","x":10,"y":14,"r":12,"couleur":"#cfe3ff","pulse":0.2},{"type":"poussiere","x":0,"y":0,"w":100,"h":80,"nombre":26},{"type":"vignette","force":0.5},{"type":"grain","force":0.04}],"zones":[{"id":"objet-1","libelle":"La gravure du temple romain","x":71,"y":1,"w":24,"h":34,"description":"Sur le mur, un temple à colonnes : ce que les savants admirent."},{"id":"objet-2","libelle":"La pile de livres","x":5,"y":50,"w":22,"h":28,"description":"Des livres imprimés, empilés : des mots nouveaux pour un temps nouveau."},{"id":"objet-3","libelle":"La presse à imprimer","x":38,"y":8,"w":28,"h":48,"description":"Une grande presse en bois : pourquoi dit-on « renaître » ?"},{"id":"objet-4","libelle":"La page d'épreuve","x":55,"y":46,"w":20,"h":28,"description":"Une page d'épreuve où manquent des mots."}],"etats":{"normal":{"filtre":"none"}}},"salle":{"titre":"La grande salle du château royal d'Amboise","reference":null,"ambiance":["vent"],"kenBurns":{"echelle":1.05,"duree":32},"effets":[{"type":"lueur","x":38,"y":46,"r":6,"couleur":"#ffcf7a","pulse":0.3,"scintille":true},{"type":"lueur","x":63,"y":45,"r":6,"couleur":"#ffcf7a","pulse":0.3,"scintille":true},{"type":"poussiere","x":0,"y":0,"w":100,"h":80,"nombre":22},{"type":"vignette","force":0.5},{"type":"grain","force":0.04}],"zones":[{"id":"objet-1","libelle":"Le trône","x":15,"y":50,"w":15,"h":30,"description":"Le trône du roi François Ier."},{"id":"objet-2","libelle":"Les portraits du roi","x":16,"y":10,"w":12,"h":40,"description":"Des portraits à ranger dans l'ordre d'une vie."},{"id":"objet-3","libelle":"La tapisserie","x":34,"y":28,"w":32,"h":26,"description":"Une tapisserie qui montre les protégés du roi."},{"id":"objet-4","libelle":"Le coffret de Dame Hélène","x":70,"y":56,"w":28,"h":22,"description":"Un coffret fermé par un cadenas à chiffres."}],"etats":{"normal":{"filtre":"none"}}},"atelier":{"titre":"L'atelier de Léonard, au manoir du Cloux, près du château","reference":null,"ambiance":["vent"],"kenBurns":{"echelle":1.05,"duree":32},"effets":[{"type":"lueur","x":41,"y":50,"r":6,"couleur":"#ffcf7a","pulse":0.4,"scintille":true},{"type":"poussiere","x":0,"y":0,"w":100,"h":80,"nombre":28},{"type":"vignette","force":0.5},{"type":"grain","force":0.04}],"zones":[{"id":"objet-1","libelle":"Les œuvres de l'atelier","x":52,"y":9,"w":20,"h":60,"description":"Peinture, ingénieur, savant : plusieurs talents."},{"id":"objet-2","libelle":"Les carnets en désordre","x":0,"y":20,"w":36,"h":50,"description":"Les carnets de Léonard, tous mêlés."},{"id":"objet-3","libelle":"La table de l'atelier","x":76,"y":40,"w":23,"h":34,"description":"Un objet qui n'appartient pas à l'atelier."},{"id":"objet-4","libelle":"Le miroir","x":36,"y":38,"w":14,"h":22,"description":"Léonard écrit à l'envers : un mot à lire dans le miroir."}],"etats":{"normal":{"filtre":"none"}}},"plans":{"titre":"Le cabinet des plans, au château d'Amboise","reference":null,"ambiance":["vent"],"kenBurns":{"echelle":1.05,"duree":32},"effets":[{"type":"rayons","x":30,"y":0,"w":50,"h":50},{"type":"poussiere","x":0,"y":0,"w":100,"h":70,"nombre":24},{"type":"vignette","force":0.5},{"type":"grain","force":0.04}],"zones":[{"id":"objet-1","libelle":"Le plan de Chambord","x":53,"y":14,"w":42,"h":34,"description":"Le plan d'un grand château."},{"id":"objet-2","libelle":"Les deux maquettes","x":2,"y":14,"w":28,"h":32,"description":"Un château fort et un château Renaissance."},{"id":"objet-3","libelle":"Les trois châteaux","x":30,"y":14,"w":23,"h":32,"description":"Trois châteaux, trois secrets."},{"id":"objet-4","libelle":"La salamandre sculptée","x":10,"y":52,"w":40,"h":22,"description":"L'emblème du roi sur la cheminée."}],"etats":{"normal":{"filtre":"none"}}},"galerie":{"titre":"La galerie des tableaux du château","reference":null,"ambiance":["vent"],"kenBurns":{"echelle":1.05,"duree":32},"effets":[{"type":"poussiere","x":0,"y":0,"w":100,"h":80,"nombre":22},{"type":"vignette","force":0.5},{"type":"grain","force":0.04}],"zones":[{"id":"objet-1","libelle":"Le tableau en perspective","x":52,"y":9,"w":26,"h":60,"description":"Un tableau en perspective à lire."},{"id":"objet-2","libelle":"Les secrets des peintres","x":20,"y":0,"w":29,"h":62,"description":"Les techniques des peintres."},{"id":"objet-3","libelle":"Le cadenas du carnet","x":0,"y":12,"w":17,"h":45,"description":"Un cadenas qui garde le carnet."},{"id":"objet-4","libelle":"La leçon de Bastien","x":80,"y":4,"w":20,"h":58,"description":"Un texte à compléter sur la perspective."}],"etats":{"normal":{"filtre":"none"}}}}},"dialogues":{"_commentaire":"Brouillon généré par le migrateur : reformuler dans le ton de chaque personnage.","accueil":{"personnage":"tommaso","texte":"Ah, vous voilà ! Je suis Tommaso, l'apprenti de maître Léonard de Vinci. Nous sommes à Amboise, au printemps 1518, et le roi François Ier prépare une grande fête au château. Ce matin, un coup de vent a fait s'envoler cinq pages du carnet de mon maître. Cinq personnes les ont ramassées, et chacune veut d'abord savoir si vous comprenez ce qu'il y a dessus. Le maître en a besoin avant la fête. Aidez-moi à retrouver les cinq pages, et notez bien le mot écrit sur chacune."},"coffre":{"personnage":"tommaso","texte":"Le coffre ne s'ouvre qu'avec les mots de chaque salle, dans l'ordre. Vous les avez notés, j'espère."},"cinematiques":{"transition-e1":{"titre":"Salle 1 — L'imprimerie de Maître Jacquet","plans":[{"decor":"imprimerie","etat":"normal","duree":8,"personnage":"jacquet","texte":"Bonjour, jeunes gens. Une page de carnet est tombée dans ma cour. Je l'ai gardée, car elle parle de mon métier. Grâce à l'imprimerie, un livre se fabrique en centaines d'exemplaires. On imprime les textes des anciens Grecs et Romains, que les savants redécouvrent. Tout le monde parle d'un temps nouveau, venu d'Italie. Dites-moi d'où il vient, et la page est à vous.","mouvement":"zoom"}]},"fin-e1":{"titre":"Fin de la salle 1","plans":[{"decor":"imprimerie","etat":"normal","duree":7,"personnage":"jacquet","texte":"Bien répondu. Le mot écrit sur la page est ANTIQUITÉ : c'est elle que la Renaissance fait renaître. Allez maintenant au château. Dame Hélène prépare la fête ; elle a ramassé une autre page.","mouvement":"glisse"}]},"transition-e2":{"titre":"Salle 2 — La grande salle d'Amboise","plans":[{"decor":"salle","etat":"normal","duree":8,"personnage":"helene","texte":"Bienvenue au château d'Amboise. Le roi a grandi ici, vous le saviez ? Depuis qu'il est roi, il fait venir d'Italie des peintres, des sculpteurs, des savants. Il aime aussi les livres et les langues. Mais attention, c'est aussi un roi qui fait la guerre. La page que j'ai ramassée parle de lui. Montrez-moi que vous le connaissez.","mouvement":"zoom"}]},"fin-e2":{"titre":"Fin de la salle 2","plans":[{"decor":"salle","etat":"normal","duree":7,"personnage":"helene","texte":"Parfait. Le mot de la page est MÉCÈNE : celui qui protège et aide les artistes et les savants. Descendez maintenant au manoir du Cloux, où travaille maître Léonard. Tommaso vous y attend.","mouvement":"glisse"}]},"transition-e3":{"titre":"Salle 3 — L'atelier du Cloux","plans":[{"decor":"atelier","etat":"normal","duree":8,"personnage":"tommaso","texte":"Voici l'atelier de mon maître. Le roi lui a donné ce manoir et un beau titre : premier peintre, ingénieur et architecte du roi. Le maître peint, dessine des machines, imagine des canaux, et il regarde tout : l'eau, les oiseaux, les plantes. Ses pages sont un vrai désordre ! La troisième page est ici, quelque part. Aidez-moi à la retrouver.","mouvement":"zoom"}]},"fin-e3":{"titre":"Fin de la salle 3","plans":[{"decor":"atelier","etat":"normal","duree":7,"personnage":"tommaso","texte":"La voilà ! Le mot est OBSERVER : le maître dit qu'il faut d'abord regarder la nature pour la comprendre et la peindre. Colombe, la fille du maître maçon, a la quatrième page. Elle est au cabinet des plans.","mouvement":"glisse"}]},"transition-e4":{"titre":"Salle 4 — Le cabinet des plans","plans":[{"decor":"plans","etat":"normal","duree":8,"personnage":"colombe","texte":"Bonjour ! Je m'appelle Colombe, mon père est maître maçon. Ici, on dessine les châteaux du roi. Ce ne sont plus des forteresses : on veut de grandes fenêtres, des escaliers magnifiques, tout bien symétrique, comme dans l'Antiquité. Le roi rêve d'un château encore plus grand, à Chambord. Lisez les plans avec moi, et je vous donne la page.","mouvement":"zoom"}]},"fin-e4":{"titre":"Fin de la salle 4","plans":[{"decor":"plans","etat":"normal","duree":7,"personnage":"colombe","texte":"Bravo ! Le mot de la page est SALAMANDRE : l'emblème du roi, sculpté sur ses châteaux. Dernière page : Bastien l'a emportée dans la galerie des tableaux.","mouvement":"glisse"}]},"transition-e5":{"titre":"Salle 5 — La galerie des tableaux","plans":[{"decor":"galerie","etat":"normal","duree":8,"personnage":"bastien","texte":"Ah, la dernière page ! Je l'étudiais, car je veux peindre comme les Italiens. Regardez ces tableaux : on dirait des fenêtres ouvertes sur le monde. Le secret, ce sont des règles de dessin. Les corps aussi ont leurs règles. Prouvez-moi que vous savez lire un tableau, et la page est à vous.","mouvement":"zoom"}]},"fin-e5":{"titre":"Fin de la salle 5","plans":[{"decor":"galerie","etat":"normal","duree":7,"personnage":"helene","texte":"Le mot de la dernière page est PERSPECTIVE . Vous avez les cinq mots ! Écrivez-les dans le coffre, dans l'ordre des salles, et le carnet de maître Léonard sera complet pour la fête.","mouvement":"glisse"}]},"fin":{"titre":"Fin de « L'Atelier de Léonard à Amboise »","plans":[{"decor":"galerie","etat":"normal","duree":7,"personnage":"bastien","texte":"Le coffre est ouvert : toutes les pages sont rassemblées. Bravo, équipe !","mouvement":"zoom"}]}},"fin_escale":{"1":{"personnage":"jacquet","texte":"Notez le mot de cette salle : il servira à ouvrir le coffre final."},"2":{"personnage":"helene","texte":"Notez le mot de cette salle : il servira à ouvrir le coffre final."},"3":{"personnage":"tommaso","texte":"Notez le mot de cette salle : il servira à ouvrir le coffre final."},"4":{"personnage":"colombe","texte":"Notez le mot de cette salle : il servira à ouvrir le coffre final."},"5":{"personnage":"bastien","texte":"Notez le mot de cette salle : il servira à ouvrir le coffre final."}}},"personnages":{"personnages":{"tommaso":{"nom":"Tommaso","court":"Tommaso","voix":{"rate":0.95,"pitch":1.0},"ton":"Apprenti curieux, émerveillé par Léonard","fiche":"Apprenti de Léonard de Vinci, 12 ans, venu d'Italie","portrait":{}},"jacquet":{"nom":"Maître Jacquet","court":"Jacquet","voix":{"rate":1.0,"pitch":1.15},"ton":"Imprimeur grave mais passionné","fiche":"Imprimeur à Amboise","portrait":{}},"helene":{"nom":"Dame Hélène","court":"Hélène","voix":{"rate":0.9,"pitch":0.9},"ton":"Dame de la cour, fine et cultivée","fiche":"Dame de la cour de François Ier","portrait":{}},"colombe":{"nom":"Colombe","court":"Colombe","voix":{"rate":1.05,"pitch":1.2},"ton":"Fille de maçon, concrète et directe","fiche":"Fille d'un maître maçon des chantiers du roi, 11 ans","portrait":{}},"bastien":{"nom":"Bastien","court":"Bastien","voix":{"rate":0.92,"pitch":1.05},"ton":"Jeune peintre fier de son art","fiche":"Jeune peintre de la cour, élève des artistes italiens","portrait":{}}}}};
